// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":9,"question":"ما المسافة التي يجب على مَن يريد المرور من أمام شخصٍ يُصلي أن يتركها؛ ليكون بذلك خارجًا من المرور بين يدي المُصلي؟","title":"ما قدر المسافة بين يدي المصلي والسُّترة؟","answer":"الجواب: المُصلي له حالان:\nأحدهما: أن يكون قد وضع سُترةً، فليس لأحدٍ أن يمرَّ بينه وبين السُّترة.\nالثاني: أن يكون ما وضع سترةً، فأحسن ما قيل في هذا أنه يُقدّر بثلاثة أذرع من قدمه، فإذا كان فوق ثلاثة أذرع لم يضرّ المرور، واحتجُّوا على هذا بأنه ﷺ لما صلَّى في الكعبة جعل بينه وبين الجدار ثلاثة أذرع، بين قدمه والجدار ثلاثة أذرع، قالوا: هذا يدل على أنَّ السترة تكون بهذه المسافة.\nهذا كله في حقِّ مَن يُصلي وحده، أما الذي يُصلي خلف الإمام فلا يقطع صلاته شيء، فالإمام سترةٌ له، فالمأموم ليس بحاجةٍ إلى سترةٍ، ولو مرَّ بين يديه امرأةٌ أو حمارٌ أو كلبٌ أو غير ذلك لم يقطع صلاتَه.","link":"https://binbaz.org.sa/fatwas/2786/ما-قدر-المسافة-بين-يدي-المصلي-والسترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0260.mp3","categories":["سترة المصلي"]},{"id":782,"question":"هل يصحّ المرور من وراء موضع السجود؟ مع العلم أنَّه لا توجد سُترة.","title":"حكم المرور من وراء موضع سجود المُصلِّي","answer":"الجواب: الواجب على المؤمن أن يحذر المرور بين يدي أخيه وهو يُصلي، كما قال النبيُّ ﷺ: لو يعلم المارُّ بين يدي المصلي ماذا عليه لكان أن يقف أربعين خيرًا له من أن يمرَّ بين يدي المصلي، فلا يجوز له المرور بين يدي المصلي، أما وراء السُّترة فلا بأس، يمر من وراء السُّترة، أو بعيدًا، يبعد عنه ثلاثة أذرع فأكثر، بعيدًا عنه، ليس بين يديه، بل بعيد عنه؛ فلا بأس.\nوالسنة للمُصلي أن يتَّخذ سترةً يُصلِّي إليها، كما قال ﷺ: إذا صلَّى أحدُكم فليُصلِّ إلى سترةٍ، وَلْيَدْنُ منها، هذه السنة، إلا المأموم، فهو تبعٌ لإمامه.","link":"https://binbaz.org.sa/fatwas/20720/حكم-المرور-من-وراء-موضع-سجود-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0605هل يصح المرور من وراء موضع السجود مع العلم أنه لا يوجد سترة؟ ابن باز فتاوى المحاضرات.mp3","categories":["سترة المصلي"]},{"id":1527,"question":"إذا كان الشخص يُصلي ركعتين في الحرم المكي، فهل يجب عليه أن يأخذ سُتْرةً؟","title":"حكم اتخاذ السُّتْرة للمصلي في الحرم المكي","answer":"الجواب:\nلا، ما يجب في وسط الحَرْم؛ لكثرة الزحمة، وهناك حديثٌ ضعيفٌ في عدم السُّتْرة، لكن العمدة على الزحمة والمشقة في السُّتْرة.","link":"https://binbaz.org.sa/fatwas/21627/حكم-اتخاذ-السترة-للمصلي-في-الحرم-المكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتخاذ السترة للمصلي في الحرم المكي.mp3","categories":["سترة المصلي"]},{"id":1611,"question":"يوجد عندنا ظاهرة من نهي النبي عليه الصلاة والسلام الصلاة خلف النائم؟","title":"ما حكم الصلاة خلف النائم؟","answer":"الجواب:\nما أتذكر شيئًا، كان يُصلي وعائشة بين يديه في الليل إذا تهجد.","link":"https://binbaz.org.sa/fatwas/21715/ما-حكم-الصلاة-خلف-الناىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة خلف النائم.mp3","categories":["سترة المصلي"]},{"id":1987,"question":"إذا كان مِن الجَنْب، مرور مِن جَنْب (المُصَلِّي)؟","title":"حكم المرور مِن جَنْب المصلي","answer":"الجواب:\nما يضر، المرور بين يديه وإلا مِنْ جنبه، ما يضر.","link":"https://binbaz.org.sa/fatwas/22103/حكم-المرور-من-جنب-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المرور من جنب المصلي وحكم اتخاذ السترة في الحرم وغيره.mp3","categories":["سترة المصلي"]},{"id":2153,"question":"بعد تسليم الإمام: هل تبقى سُتْرةُ الإمام سُتْرةً للمأموم (المسبوق)؟","title":"هلسُتْرةُ الإمام بعد تسليمه سُتْرة للمأموم؟","answer":"الجواب:\nلا، إذا تيسرت له السُّترة وإلا فيُكْمِل ولو بلا سُتْرةٍ والحمد لله، وإن كانت حوله سُتْرة فجعلها أمامه فطيبٌ، إن كان يخشى أن يمرَّ أحدٌ؛ لأنه في المسجد الحرام بين يدي الكعبة ما يحتاج إلى سُترةٍ، وهذا للرجل والمرأة جميعًا.\nس: في مكة فقط؟\nج: نعم، إذا كان هناك زحامٌ ولا يستطيع السُّترة؛ فتكون معفوًّا عنها، سواء كان في المدينة أو في غيرها: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nس: في أيّ مكانٍ؟\nج: في أي مكانٍ.","link":"https://binbaz.org.sa/fatwas/22272/هل-سترة-الامام-بعد-تسليمه-سترة-للماموم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في السترة للإمام.mp3","categories":["سترة المصلي"]},{"id":2373,"question":"الصبي دون سن التمييز، ثلاث سنوات أربع سنوات، في الصف، يقطع الصف؟","title":"هل يقطع الصبيُّ غير المُمَيِّز صَفَّ الصلاة؟","answer":"الجواب:\nالأقرب أنه لا يقطع، مثل الحجر والمركأ، لكن إذا كان خلف الناس حتى لا يشوش على الناس أفضل، كونه يبقى في البيوت أو خلف الناس؛ حتى لا يشوشوا على المصلين؛ يكون أسْلَم.","link":"https://binbaz.org.sa/fatwas/22498/هل-يقطع-الصبي-غير-المميز-صف-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصبي دون سن التمييز هل يقطع الصف في الصلاة.mp3","categories":["سترة المصلي"]},{"id":2453,"question":"الأطفال يصعب التحرُّز منهم في المرور بينه وبين السُّترة؟","title":"حكم مرور الأطفال والدواب أمام المصلي","answer":"الجواب:\nعلى كل حال يَردُّه إذا تيسَّر، وإذا غلبوا لا يضره، لكن إذا تيسر ردهم، حتى الدواب؛ العَنْز والبعير والبقرة كله يردهم إذا تيسر، وإذا غلبه لا يقطع صلاته إلا واحد مِن ثلاث: المرأة الحائض -يعني البالغة- والحمار، والكلب الأسود، هذه الثلاث هي التي تقطع، وما سواها لا يقطع، لكن يُمْنَع لا يمر، لكن إذا مر لا يقطع.","link":"https://binbaz.org.sa/fatwas/22582/حكم-مرور-الاطفال-والدواب-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مرور الأطفال بين المصلي وبين السترة.mp3","categories":["سترة المصلي"]},{"id":2455,"question":"المرأة الحائض والكلب الأسود إذا مروا بين يدي المصلي هل يبطلها أم يبطل أجرها؟","title":"معنى إبطال الصلاة بمرور الحائض والكلب","answer":"الجواب:\nيستأنفها من أولها، إذا مرت المرأة والحمار والكلب الأسود بطلت، يستأنفها من أولها.\nس: بمعنى يبطل الصلاة؟\nالشيخ: نعم إن كان فريضة وجب عليه أن يستأنفها، وإن كانت نافلة مخير إن استأنفها فهو أفضل.\nس: الشاهد يبطلها؟\nالشيخ: يقطعها يعني يبطلها.\nس: المرأة الحائض التي عليها الدورة الشهرية؟\nالشيخ: لا، البالغة يعني، سواء كانت مَحْرمًا أو ما هي بِمَحْرَم؛ زوجه أو أمه أو أخته؛ كله واحد.","link":"https://binbaz.org.sa/fatwas/22584/معنى-ابطال-الصلاة-بمرور-الحاىض-والكلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا مر بين يدي المصلي حائضا أو كلبا هل تبطل الصلاة أم يبطل أجرها.mp3","categories":["سترة المصلي"]},{"id":2457,"question":"الرسول ﷺ كان متخذًا عائشة سُترة؟","title":"هل يصلح اتخاذ الإنسان سُترة في الصلاة؟","answer":"الجواب:\nلا، هي في فراشها نائمة.\nس: إذا كان إنسان جالسًا أمامك يمكن أن تتخذه سُترة؟\nالشيخ: إذا كان بيجلس حتى تُكمل يصير سُترة... إذا قال: سأجلس حتى تصلي؛ جزاه الله خيرًا.","link":"https://binbaz.org.sa/fatwas/22586/هل-يصلح-اتخاذ-الانسان-سترة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون الإنسان سترة في الصلاة.mp3","categories":["سترة المصلي"]},{"id":2862,"question":"السترة هل هي واجبة؟","title":"حكم السُّترة للمصلي وحكم مَن قُطعت صلاته","answer":"الجواب: سنة مؤكدة للفرد والإمام بس.\nس: الثلاثة الذين يقطعون الصلاة إذا مروا أمام الشخص يستأنف من جديد؟\nالشيخ: نعم إذا كانوا قريبين منه أو بينه وبين السترة وهو إمام أو منفرد، أما المأمومون ما يضرهم، لو مروا بين أيدي المأموم ما يضرهم.\nس: ثبت أن النبي ﷺ صلى من غير سُترة؟\nالشيخ: نعم.\nس: في مثل هذه الحال الإنسان في بعض الأحيان يصلي بغير سُترة؟\nالشيخ: نعم؛ لأن الرسول ﷺ في بعض الأحيان صلى بغير سُترة.\nس: ممكن إنسان يصلي بدون سُترة أيضًا؟\nالشيخ: إذا ما تيسّرت السُّترة، لكن السُّترة أفضل.","link":"https://binbaz.org.sa/fatwas/23015/حكم-السترة-للمصلي-وحكم-من-قطعت-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السترة للمصلي، وحكم من قُطعت صلاته.mp3","categories":["سترة المصلي"]},{"id":3108,"question":"الأطفال والبنت الصغيرة، يعني الجارية، إذا مروا بين يدي المصلي هل له أن يمنعهم أم الأمر واسع؟","title":"حكم مرور الأطفال الصغار أمام المُصلي","answer":"الجواب: إذا تيسّر.\nس: وإذا لم يتيسّر؟\nالشيخ: ما يضرونه.","link":"https://binbaz.org.sa/fatwas/23268/حكم-مرور-الاطفال-الصغار-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا مرَّ الأطفال والبنت الصغيرة بين يدي المصلي.mp3","categories":["سترة المصلي"]},{"id":3347,"question":"مرور ابن عباس رضي الله عنهما أمام الرسول ﷺ أو أمام الصفوف فقط؟","title":"حكم المرور أمام المصلّين في صلاة الجماعة","answer":"الجواب: في الصف.\nالطالب: ليس أمام الرسول ﷺ؟\n الشيخ: من أمام بعض الصف.\nس: يؤخذ من هذا عدم قطع الصلاة...؟\nالشيخ: هذا مِنْ حُجَّة أن المأموم سُتْرةُ إمامِه سُتْرةٌ له.","link":"https://binbaz.org.sa/fatwas/23513/حكم-المرور-امام-المصلين-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث فمررت بين يدي بعض الصف... حجة أن المأموم سترة إمامه سترة له.mp3","categories":["شروح الحديث","سترة المصلي"]},{"id":3486,"question":"إذا كان يصلي في حجرة، ولا أحد يقطعه؟","title":"حكم السُّترة للمصلي إذا كان في حجرة","answer":"الجواب: ولو في حجرة، الجدار اللي في الحجرة يكفي، جدار الحجرة سُترة له.\nس: الخط هل هو ثابت؟\nالشيخ: ثابت نعم، إذا ما تيسر شيء يخط خطًا.","link":"https://binbaz.org.sa/fatwas/23663/حكم-السترة-للمصلي-اذا-كان-في-حجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السترة للمصلي إذا كان في حجرة، ولا أحد يقطعه.mp3","categories":["سترة المصلي"]},{"id":3487,"question":"إذا كان الإنسان مأمومًا ثم انتهى الإمام من صلاته، وبقي له ركعتان، وقام الذين أمامه، وانصرفوا، وأمامه سترة قريبة فهل يَدْنو منها، أو يجلس مكانه؟","title":"ما يفعل مَنْ زالت السترة عنه أثناء الصلاة؟","answer":"الجواب: إن كان يخشى شيئًا، وإلا بمكانه، ويكفي، والحمد لله. إذا كان يخشى أن الناس يمرون يتقدّم.\nس: إذا كان في الحرم بعيدًا عن الكعبة؟\nالشيخ: ولو، ما دام داخل المسجد ما يحتاج سُترة.","link":"https://binbaz.org.sa/fatwas/23665/ما-يفعل-من-زالت-السترة-عنه-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من زالت السترة عنه أثناء الصلاة هل يدن منها او يجلس مكانه.mp3","categories":["سترة المصلي"]},{"id":3489,"question":"هل السترة واجبة يا شيخ؟","title":"هل السترة للمصلي واجبة أم مستحبة؟","answer":"الجواب: سُنَّة، يقول ﷺ: إذا صلى أحدكم فليصل إلى سترة، وليدن منها، وثبت في النسائي وغيره أنه صلى في بعض الأحيان إلى غير سترة عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23667/هل-السترة-للمصلي-واجبة-ام-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السترة للمصلي.mp3","categories":["سترة المصلي"]},{"id":3490,"question":"رجل يصلي أمامي ثم جعلته سترة لي، هو يصلي، وأنا أصلي؟","title":"حكم سُترة المصلي وما يقطعُ الصلاة","answer":"الجواب: ما يضر، الأمر واسع.\nس: المرأة في الحرم؟\nالشيخ: لا يضر، في الحرم ما يضر.\nس: المرأة بها مس، وعندما تصلي تجد أن الكلب يمر أمامها، وهكذا؟\nالشيخ: إذا مر منها قريبًا منها في ثلاثة أذرع، أو بينها وبين السترة يقطع، إذا كان أسود خاصة.\nس: هي تراه فقط؟\nالشيخ: إذا كان أسود خاصة.\nس: تعيد الصلاة أحسن الله إليك؟\nالشيخ: إذا مر بين يدي المصلي، أو بينه وبين السترة؛ يعيد الصلاة، إذا كانت فريضة يلزمه.\nس: شيخ قلتم يقطع الصلاة إذا كانت فريضة، إذا كانت نافلة؟\nالشيخ: يقطعها لكن ما يلزمه الإعادة لأنها نافلة، إن أعاد حسن، وإلا ما تلزمه لأنها نافلة.\nس: أحسن الله إليك الحديث الوارد في النهي عن الصمود للسترة؟\nالشيخ: ضعيف.\nس: يعني يَصْمُد لها لا حرج؟\nالشيخ: لا بأس، نعم.\nس: هذه السنة؟\nالشيخ: النبي ﷺ قال: فليجعل تلقاء وجهه فليصل إليه، تلقاء وجه، أما حديث: يجعلها عن يمينه، أو شماله: فضعيف.","link":"https://binbaz.org.sa/fatwas/23668/حكم-سترة-المصلي-وما-يقطع-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل متفرقة في سترة المصلي.mp3","categories":["سترة المصلي"]},{"id":3492,"question":"هل هناك دليل على النهي عن الصلاة خلف النائم؟","title":"حكم الصلاة خلف النائم وتقلّبه أمام المصلي","answer":"الجواب: لا، لا حرج في ذلك.\nس: التقلّب، وهو نائم؟\nالشيخ: ما يضر.\nس: ما يعد مرورًا؟\nالشيخ: لا ما يعد مرورًا.\nس: انسلالها بين يدي رسول الله ﷺ أليس هذا مرورًا؟\nالشيخ: انسلالها ما هو مرور، تنسلّ من الفراش، تنسلّ من جهة رأسها.\nس: تقول: فأنسلّ من عند رجليه؟\nالشيخ: سواء من عند رجليه، أو من عند رأسه، كله واحد، ما يسمى مرورًا، المرور الذي يأتي من جانب إلى جانب.\nس: في بعض الأحاديث أن عائشة رضي الله عنها كانت على السرير، ألا يكون السرير كله...؟\nالشيخ: هي فوق السرير، والنبي ﷺ كان إذا سجد غمز رجليها حتى تكف رجليها، وهي نائمة.","link":"https://binbaz.org.sa/fatwas/23670/حكم-الصلاة-خلف-الناىم-وتقلبه-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة خلف النائم.mp3","categories":["سترة المصلي"]},{"id":3493,"question":"المرأة إذا مرت بين يدي الرجل والمرأة؟","title":"هل يقطع مرورُ المرأة صلاةَ الرجل والمرأة؟","answer":"الجواب: نعم عام، الثلاثة تقطع صلاة الرجل والمرأة (الحمار، والكلب الأسود، والمرأة)، المرأة تقطع صلاة المرأة.","link":"https://binbaz.org.sa/fatwas/23671/هل-يقطع-مرور-المراة-صلاة-الرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المرأة إذا مرت بين يدي الرجل والمرأة في الصلاة.mp3","categories":["سترة المصلي"]},{"id":3494,"question":"هل تنقطع صلاة المأموم (بالمرور أمامه)؟","title":"هل تنقطع صلاة المأموم بالمرور أمامه؟","answer":"الجواب: لا، ما تنقطع، سُترة الإمام سُترة له، لو مر بين يدي المأموم شيء ما ينقطع، قد مر الحمار الذي عليه ابن عباس بين يدي المأمومين، ولم  يضرهم، سُترة الإمام سُترة لهم.","link":"https://binbaz.org.sa/fatwas/23672/هل-تنقطع-صلاة-الماموم-بالمرور-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سترة الإمام سترة للمأمومين.mp3","categories":["سترة المصلي"]},{"id":3523,"question":"ابتدار الصحابة للسواري يدل على الصف الأول أين هم؟","title":"معنى ابتدار الصحابة السواري يصلون إليها","answer":"الجواب: يدل على استقبال السترة وقت الصلاة.\nس: ولو كان الصف الأول فاتهم؟\nالشيخ: ظاهر السياق أنهم يبتدرون السواري حتى يصلون إليها السنة،  سنة المغرب، السنة التي بين الأذانين، بين الأذان والإقامة.","link":"https://binbaz.org.sa/fatwas/23704/معنى-ابتدار-الصحابة-السواري-يصلون-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث ..قام ناس من أصحاب النبي يبتدرون السواري...mp3","categories":["سترة المصلي","شروح الحديث"]},{"id":3524,"question":"إذا وجد سترة في الصف الثاني، وفي الصف الأول فُرْجَة لا سُتْرة فيها، أيهما يُقدّم؟","title":"حكم من وجد فُرجة بالصف الأول دون سُترة","answer":"الجواب: يصلي في محله والحمد لله، إن كان في الصف الأول فالأول، وإن كان في الثاني فالثاني، فالسترة ما هي بواجبة، مستحبة، وإذا كان لا يخشى شيئًا فالأمر واسع، إذا كان ما يخشى مرور أحد.","link":"https://binbaz.org.sa/fatwas/23705/حكم-من-وجد-فرجة-بالصف-الاول-دون-سترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إذا وجد سترة في الصف الثاني وفي الصف الأول فرجة لا سترة فيها.mp3","categories":["سترة المصلي"]},{"id":4497,"question":"الحديث قوله: \"يبتدرون السواري\" يعني: سترةً؟","title":"معنى حديث \"يبتدرون السواري\"","answer":"الجواب: نعم، سترة يُصلون إليها يعني.\nس: يبتدرون السَّواري؟\nج: للسترة.\nس: ويتركون الصفَّ الأول؟\nج: يتقدَّمون للسواري ثم يعودون إلى أماكنهم.","link":"https://binbaz.org.sa/fatwas/24777/معنى-حديث-يبتدرون-السواري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى حديث يبتدرون السواري.mp3","categories":["سترة المصلي","شروح الحديث"]},{"id":4582,"question":"في الحرمين إذا قطعت المرأة؟","title":"هل تقطع المرأة الصلاة في الحرمين؟","answer":"الجواب: لا، في المسجد الحرام يُعفى عنه للضَّرورة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]؛ ولهذا الصحيح عند العلماء أنها لا تقطع الصلاة في المسجد الحرام؛ للزحام.","link":"https://binbaz.org.sa/fatwas/24868/هل-تقطع-المراة-الصلاة-في-الحرمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقطع المرأة الصلاة في الحرمين.mp3","categories":["سترة المصلي"]},{"id":4583,"question":"حديث ابن عباس الثاني قوله: \"صلَّى النبيُّ ﷺ إلى غير جدارٍ\"؟","title":"حكم السترة والمرور أمام المصلي","answer":"الجواب: احتجَّ به بعضُهم على عدم السترة، ولكن ليس بصريحٍ؛ لأنه إنما نفى الجدار فقط، وما نفى السترة، فيحتمل أنه ﷺ صلَّى إلى عنزةٍ، فلا يلزم من عدم الجدار عدم السترة كما تقدم.\nس: ما هناك دليلٌ صريح للجمهور على عدم السُّترة؟\nج: ما أعلم، حديث ابن عباس، لكن متّهم بالحجاج بن أرطأة، كما تقدم.\nس: إذا لم يتَّخذ الإمامُ سترةً، ومرَّ بين يدي بعض الصفِّ حمار؟\nج: ما يضرُّ، الأمر على الإمام.","link":"https://binbaz.org.sa/fatwas/24870/حكم-السترة-والمرور-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألةٌ السترة ووجوبها.mp3","categories":["سترة المصلي"]},{"id":4944,"question":"سائل يقول: السترة للصلاة: هل يجوز تناول المصحف الشريف ليكون سترة لي أو بعض كتب العلم؟","title":"هل يجوز جعل المصحف سُترة للمصلي؟","answer":"الجواب: أما المصحف فالأوْلى أن يكون في محل مرتفع ما يُمتهن، فإذا جعل شيئًا من كتب العلم أمامه، ما عنده سترة؛ فالظاهر لا أعلم في هذا بأسًا، إن كان المحل نظيفًا فلا بأس به، أما المصحف محل نظر.","link":"https://binbaz.org.sa/fatwas/27369/هل-يجوز-جعل-المصحف-سترة-للمصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز جعل المصحف سُترة للمصلي؟.mp3","categories":["سترة المصلي"]},{"id":4960,"question":"في الحديث أنه صلى إلى غير جدار، وفي لفظ كما ذكر الشارح...؟","title":"هل صح حديث في الصلاة إلى غير سترة؟","answer":"الجواب: قد يكون إلى سُتْرة أخرى، ما هو بلازم، ليس بقطع أنه ما له سترة، قد تكون له سُتْرة عَنَزَة، ونحوها.\nس: ذكر الحافظ رواية البزار أنه إلى غير شيء يستره؟\nالشيخ: يحتمل؛ لأنه فعل هذا لما زار محل العباس، فدل على أن السترة ما هي بواجبة سنة، ليست بواجبة، فالحاصل أنه مر بين يدي بعض الصف، والمرور بين يدي الصف لا يقطع الصلاة، حتى ولو كان الإمام ما له سُتْرة.","link":"https://binbaz.org.sa/fatwas/27563/هل-صح-حديث-في-الصلاة-الى-غير-سترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صح حديث في الصلاة إلى غير سترة؟.mp3","categories":["سترة المصلي"]},{"id":5028,"question":"هل يجوز  مرور المرأة في الحرم أمام الصفوف؟","title":"حكم اتخاذ السترة في الحرم","answer":"الجواب: الحرم لا حرج؛ لأن المشقة داعية إلى ذلك، فالحرم المكي لا يضر؛ لأن الناس في حاجة إلى هذا شيء.\nس: وهل يتخذ سترة؟\nالشيخ: لا ما يتخذ سترة، مَعْفُوٌ عنها.","link":"https://binbaz.org.sa/fatwas/28934/حكم-اتخاذ-السترة-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتخاذ السترة في الحرم.mp3","categories":["سترة المصلي"]},{"id":5029,"question":"اتخاذ سترة ضمنية كأن تجعل الخط الذي في المسجد سُترة لك، الخط الذي على المفارش؟","title":"مقدار السترة للمصلي، وحكم اتخاذها بالخطوط","answer":"الجواب: لا، تحط عصا وإلا كرسي وإلا شيء، الخط ما يصلح، خط تخطه أنت في الأرض، تخط خَطًّا يبين، يشوفونه الناس في الأرض، تراب أو رمل، تخط فيه خَطًّا.\nس: ثلاثة أذرع مِن رِجْل المصلي؟\nالشيخ: مِنْ رِجْلِه القدم.","link":"https://binbaz.org.sa/fatwas/28935/مقدار-السترة-للمصلي-وحكم-اتخاذها-بالخطوط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مقدار السترة للمصلي، وحكم اتخاذها بالخطوط.mp3","categories":["سترة المصلي"]},{"id":5030,"question":"إذا كان المصلي في صحراء هل يتخذ سُترة؟","title":"حكم السترة للمصلي في الصحراء","answer":"الجواب: نعم.\nس: طيب يضع عصا؟\nالشيخ: عصا، وإلا خط، الذي تيسر، وإلا كرسي، وإلا حجر.\nس: الحذاء؟\nالشيخ: لا، كرسي قدر ذراع إلا ربع تقريبًا، يقول ﷺ في الحديث الصحيح: يقطع صلاة المرء المسلم ما لم يكن بين يديه مثل مؤخرة الرَّحْل: الحمار، والكلب الأسود، والمرأة فهذا يدل على مؤخرة الرحل تقارب ذراعًا إلا ربع...","link":"https://binbaz.org.sa/fatwas/28936/حكم-السترة-للمصلي-في-الصحراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السترة للمصلي في الصحراء.mp3","categories":["سترة المصلي"]},{"id":5031,"question":"اتخاذ السترة واجب؟","title":"هل السترة للمصلي مستحبة أم واجبة؟","answer":"الجواب: ظاهر الأحاديث الوجوب؛ قوله ﷺ: إذا صلَّى أحدُكم فليصلِّ إلى سُترةٍ وليَدْنُ منها، لكن المعروف عند أهل العلم أنها سنة مؤكدة؛ لأنه يُروى عنه ﷺ أنه صلى في بعض الأماكن من دون سترة كما رواه الفضل بن العباس، فكونه صلى إلى غير سترة في بعض الأحيان يدل على عدم الوجوب.","link":"https://binbaz.org.sa/fatwas/28937/هل-السترة-للمصلي-مستحبة-ام-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل السترة للمصلي مستحبة أم واجبة؟.mp3","categories":["سترة المصلي"]},{"id":6193,"question":"هل يجوز للمصلي أن يضع نعليه سترة له في الصلاة؟","title":"حكم وضع النعلين سترة أمام المصلي","answer":"الجواب: السنة لا، لا يجعلها أمامه، إن تيسر له سترة مثل الجدار، أو سارية، أو عمود، عصا يطرحها، خط يخطه إذا ما وجد شيئًا، أما النعال فالسنة أن يلبسها ويصلي فيها، أو يجعلها بين رجليه، لا يجعلها أمامه، النبي ﷺ قال: فليصل فيهما، أو ليجعلهما بين رجليه وإذا كان إمامًا، أو منفردًا جعلهما عن يساره، لا يجعلهما أمامه لا.","link":"https://binbaz.org.sa/fatwas/1676/حكم-وضع-النعلين-سترة-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_550.mp3","categories":["سترة المصلي"]},{"id":6740,"question":"ما حكم الذي يمر، والمصلي يصلي على بعد ثلاثة أمتار، علمًا بأنه لا يوجد سترة بينه وبين المصلي؟","title":"حكم المرور بين يدي من يصلي إلى غير سترة","answer":"الجواب: المصلي هو الذي فرط، فلا شيء عليه، لكن لا يقرب منه، يمر بعيدًا، النبي ﷺ صلى في الكعبة إلى ثلاثة أذرع، بينه وبين الجدار ثلاثة أذرع، فإذا كان بعيدًا عنه بينه، وبينه ثلاثة أذرع، أو أكثر؛ لا يضره، أما إن كان هناك ستره؛ فلا يمر بينه وبينها، يمر من ورائها. السؤال: طيب يا شيخ بالنسبة في صلاة الأئمة في الحرم إذا أتى يوم الجمعة يقف الإمام في أحد المصابيح، وهم محاذون الجوانب؟ الجواب: ما يضر، ما يضر مكة فيها... من جهاتها الأربع. الطالب: أنا ما أقول يعني قصدي .. متقدم ..؟ الجواب: الذي وراه  ... والذي من جهة .. ما يضر. السؤال: أنا طالب أسكن السكن الجامعي، وهناك بعض الطلاب هداهم الله لا يؤدون الصلاة في المسجد، وأنا أعرف بعضهم ونصحتهم، ولكن بلا فائدة، فماذا أعمل، وإذا تركتهم هل أنا مخطئ، أرشدني جزاكم الله خيرًا؟","link":"https://binbaz.org.sa/fatwas/2619/حكم-المرور-بين-يدي-من-يصلي-الى-غير-سترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1115.mp3","categories":["سترة المصلي"]},{"id":6743,"question":"ما حكم الذي يمر، والمصلي يصلي على بعد ثلاثة أمتار، علمًا بأنه لا يوجد سترة بينه وبين المصلي؟","title":"حكم المرور بين يدي من يصلي إلى غير سترة","answer":"الجواب: المصلي هو الذي فرط، فلا شيء عليه، لكن لا يقرب منه، يمر بعيدًا، النبي ﷺ صلى في الكعبة إلى ثلاثة أذرع، بينه وبين الجدار ثلاثة أذرع، فإذا كان بعيدًا عنه بينه، وبينه ثلاثة أذرع، أو أكثر؛ لا يضره، أما إن كان هناك ستره؛ فلا يمر بينه وبينها، يمر من ورائها. السؤال: طيب يا شيخ بالنسبة في صلاة الأئمة في الحرم إذا أتى يوم الجمعة يقف الإمام في أحد المصابيح، وهم محاذون الجوانب؟ الجواب: ما يضر، ما يضر مكة فيها... من جهاتها الأربع. الطالب: أنا ما أقول يعني قصدي .. متقدم ..؟ الجواب: الذي وراه  ... والذي من جهة .. ما يضر. السؤال: أنا طالب أسكن السكن الجامعي، وهناك بعض الطلاب هداهم الله لا يؤدون الصلاة في المسجد، وأنا أعرف بعضهم ونصحتهم، ولكن بلا فائدة، فماذا أعمل، وإذا تركتهم هل أنا مخطئ، أرشدني جزاكم الله خيرًا؟","link":"https://binbaz.org.sa/fatwas/2619/حكم-المرور-بين-يدي-من-يصلي-الى-غير-سترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1115.mp3","categories":["سترة المصلي"]},{"id":7463,"question":"الأخ أيضاً يستمع دائماً للأذان أو نقل الأذان من المسجد الحرام، فيقول: بالرغم من بعد المسافة نسمع دائماً عند صلاة المغرب والعشاء صريخ وضجيج أطفال في بيت الله الحرام، هل هذا يجوز في هذا المكان أو في أي مسجد من المساجد؟","title":"اصطحاب النساء لأولادهن إلى المساجد","answer":"الجواب:  لا حرج في ذلك؛ لأن من طبيعة الطفل أنه يحصل منه هذا الشيء، وكان الأطفال في عهد النبي ﷺ يسمعهم النبي يسمع صراخهم، ولم يمنع أمهاتهم من الحضور، بل ذلك جائز، ومن طبيعة الطفل أن يحصل له بعض الصراخ، وقد ثبت عنه ﷺ ما يدل على أنه يسمع ذلك ولم يمنع، بل قال: إنه يقوم في الصلاة ويريد تطويلها فيسمع بكاء الصبي فيخفف؛ لئلا تفتتن أمه.  هذا يدل على أنه أقرهن على ذلك، وراعهن في الصلاة أيضاً عليه الصلاة والسلام؛ ولأن منع الأطفال معناه وسيلة إلى منع الأمهات من الحضور، وقد يكون حضورهن فيه فائدة للتأسي بالإمام في الصلاة، والطمأنينة فيها، ومعرفتها كما ينبغي، أو لتسمع فائدة من المكبر أو من إمام في العلم.  فالحاصل: أن حضورها إلى المسجد مع التستر والتحجب والعناية وعدم الطيب فيه فوائد، فإن كانت لا تأتي إلا بتبرج وإظهار محاسنها أو الطيب فلا يجوز لها ذلك، بل صلاتها في بيتها أولى، وبكل حال صلاتها في بيتها أولى وأفضل إلا إذا كان خروجها تستفيد منه فائدة واضحة كالنشاط في قيام رمضان، وكسماع العلم والفائدة، أو التأسي بالإمام في صلاته الراكدة والطمأنينة؛ لأنها تجهل كيفية الصلاة كما ينبغي، فتستفيد صفة الصلاة والطمأنينة فيها، تستفيد سماع المواعظ والذكرى، فهذا قد يعني يجعل خروجها أولى لهذه المصلحة، وإلا فالأصل أن بيتها خير لها، صلاتها في البيت أولى لها.\nأما خروجها متبرجة بالملابس الحسنة الفاتنة، أو بإبراز بعض محاسنها، أو إظهار الطيب الذي يعني قد يسبب الفتنة بمن تمر عليهم، فكل هذا لا يجوز، بل يجب عليها أن تبقى في بيتها ولا تخرج بهذه الأحوال التي تفتن الناس وتضر الناس.\nأما الطفل فلا بأس بوجوده معها، لكن تتحفظ منه، وتجعله في محل محفوظ حتى لا يقذر المسجد ولا يؤذي المصلين، وإذا دعت الحاجة إلى حمله عند الحاجة ليسكت فلا بأس، فقد حمل النبي ﷺ أمامة بنت زينب ، حملها وهو يصلي بالناس عليه الصلاة والسلام.\nفالحاصل: أن وجود الأطفال في المسجد وحملهن حتى في الصلاة لا حرج فيه عند الحاجة؛ ولكن ينبغي أن يراعى في ذلك سلامة الطفل من النجاسات حتى لا ينجس أمه.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4181/اصطحاب-النساء-لاولادهن-الى-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_001/00105.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":7504,"question":"سؤاله الآخر يقول: هل يجوز من حضر إلى المسجد متأخر وصلى تحية المسجد أمام وجه مصلي آخر، أو ضايقه حتى كاد يخرج من مكانه، وفي بعض الحالات يخرج ويترك المكان له، وهذا كثير ما يحدث، والبعض يضع سجادة أو إحرامه ويذهب للطواف ليحجز المكان في المسجد الحرام، نرجو الإفادة عن هذين النقطتين؟","title":"حكم مضايقة المصلين في الصفوف وحجز الأماكن","answer":"الجواب: ليس للمؤمن أن يضايق أخاه في الصف، بل يصلي حيث انتهى، بل يقف ويصف مع الناس حيث انتهى الصف، وليس له أن يفرق بين اثنين كما جاءت به النصوص، لكن إذا وجد فرجة تسع له فإنه لا بأس أن يدخل فيها ويسدها؛ لأن المسلمين مأمورون بسد الفرج وبالتراص في الصفوف، وله أن يصلي إذا كان أمامه أحد له أن يصلي تحية المسجد أو الراتبة، وإن كان أمامه شخص جالس كالإمام ونحو ذلك لا بأس، لا حرج عليه في ذلك، وإنما يجب عليه أن يلاحظ عدم الإيذاء لإخوانه المسلمين، بل يصف مع الناس حيث انتهت الصفوف، ولا يؤذي الناس بمضايقتهم في الصفوف ما لم يجد فرجة ... تسع له، فلا بأس أن يسدها كما هو مأمور بذلك. نعم.\nالمقدم: طيب! وبالنسبة لحجز المكان بسجادة؟\nالشيخ: كذلك حجز المكان؛ ليس له حجز المكان، ليس لأحد أن يحجز المكان لا في يوم الجمعة ولا في غيره، بل ينبغي له أن يأتي إلى الصلاة على نية الإقامة في المسجد حتى يصلي مع الناس، أما أنه يأتي يحط يجعل في المكان سجادة أو شيئاً آخر حتى يرجع، يذهب إلى بيته، أو إلى الطواف، أو إلى شيء آخر ثم يرجع ليس له ذلك؛ لأن هذا يمنع منه المتقدمين إلى الصلاة وإلى الصفوف، فالواجب على المؤمن أن يدع هذه الأمور، وأن يقصد الصلاة ليقيم في المسجد لا ليضع عمامة أو عباءة أو سجادة أو غير ذلك ثم يخرج لحاجاته الأخرى. نعم.","link":"https://binbaz.org.sa/fatwas/4465/حكم-مضايقة-المصلين-في-الصفوف-وحجز-الاماكن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00803.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":7505,"question":"سؤاله الآخر يقول: هل المرور أمام أوجه المصلين حرام في جميع المساجد، وأيضاً في المسجد الحرام يحدث كثيراً؟ نرجو التوجيه وفقكم الله.","title":"حكم المرور بين يدي المصلي ومقدار السترة","answer":"الجواب: ليس للمسلم أن يمر بين المصلين أمامهم؛ لأن النبي ﷺ قال: لو يعلم المار بين يدي المصلي ماذا عليه لكان أن يقف أربعين خيراً له من أن يمر بين يديه فليس للمسلم أن يمر بين يدي إخوانه وهم يصلون، إذا كان الإمام لم يقم الصلاة، يصلون النوافل، ينتظرون الصلاة أو بعد الصلاة، ليس له أن يمر بين أيديهم، بل يسلك مسلكاً آخر حيث أمكن، حيث يلتمس الموقف مع المصلين على طريقة لا يمر بها بين يدي المصلي قريباً منه، أما إذا كان بعيداً منه فلا يضره ذلك، أو أمامه سترة، بين المصلي وبينه سترة، فلا بأس بذلك، وهكذا إذا كان الناس في الصلاة قد أقيمت الصلاة، فلا بأس يمر بين يدي المصلين وهم في الصلاة؛ لأنهم مستورون بالإمام؛ بسترة الإمام، فلا يضر من مر بين أيديهم وهم يصلون خلف الإمام، ولكن لا يمر بين يدي المصلي فرداً، أو بين يدي الإمام، ولا يمر بينه وبين السترة أيضاً، بل يكون بعيداً عن ذلك، أو من وراء السترة لا بأس، للحديث السابق. نعم.\nالمقدم: سماحة الشيخ! ممكن نعرف مقدار قبلة الشخص التي ممكن أن يمر الإنسان بعدها؟\nالشيخ: اختلف العلماء في هذا، وأحسن ما قيل في ذلك: أنه إذا كان أبعد من ثلاثة أذرع من قدم المصلي فلا يضر؛ لأنه إذا أراد أن يرده يحتاج إلى خطوات، يحتاج إلى أن يتقدم خطوات، وكان النبي ﷺ (لما صلى في الكعبة جعل بينه وبين الجدار ثلاثة أذرع)، فإذا كان بعيداً عن محل المصلي ثلاثة أذرع فأكثر بعيداً عنه فلا يضر ذلك، ولكن الأولى بالمصلي أن يتخذ سترة، إذا تيسر له سترة يتخذ سترة، كالسارية، والجدار، أو عصا يركزها، أو ما أشبه ذلك إذا تيسر له ذلك حتى يوسع على الناس في المرور ولا يحرجهم، والذي يرى السترة ليس له أن يمر بينها وبين المصلي بل يمر من ورائها؛ كان النبي صلى الله عليه وسلم يتخذ سترة في أسفاره وفي الحضر عليه الصلاة والسلام، ويقول ﷺ: إذا صلى أحدكم فليصل إلى سترة وليدن منها فاتخاذ سترة سنة مؤكدة، والدنو منها سنة أيضاً، وليست واجبة لكنها سنة. نعم..\nالمقدم: إذاً: نستطيع أن نقول: أن الإنسان إذا مد يده لمن أراد أن يمر أمامه ولا يطوله إلا بخطى، فإنه في .....\nالشيخ: هذا معفو عنه في أصح الأقوال. نعم.","link":"https://binbaz.org.sa/fatwas/4466/حكم-المرور-بين-يدي-المصلي-ومقدار-السترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00804.mp3","categories":["سترة المصلي"]},{"id":7506,"question":"سؤاله الأخير يقول: هل يجوز دخول المسجد والجلوس فيه دون الصلاة حتى يؤذن؟ أرجو إفادتي جزاكم الله خير الجزاء.","title":"حكم دخول المسجد للراحة والنوم","answer":"الجواب: لا بأس أن يدخل المسجد ويجلس فيه للراحة أو للنوم؛ القائلة، أو ما أشبه ذلك، لا بأس بذلك، فقد كان بعض الصحابة ينام في المسجد في عهد النبي عليه الصلاة والسلام، ولكن ليس له أن يجلس.. ما ينبغي له الجلوس إلا بعد التحية إذا كان على طهارة، إذا كان على وضوء يصلي ركعتين ثم يجلس، أما إن كان على غير طهارة فلا حرج عليه يجلس والحمد لله، ولا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/4467/حكم-دخول-المسجد-للراحة-والنوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00805.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":7624,"question":"السؤال الثاني من المستمع عبد الله إبراهيم بخاري من مكة المكرمة يقول: ما حكم المرور بين يدي المصلي في المسجد الحرام، وهل الحديث خاص في المسجد الحرام أم يشمل مكة ومساجدها؟ وهل يأثم من مر بين المصلي من غير قصد وليس متعمداً؟","title":"ما حكم المرور بين يدي المصلي في المسجد الحرام؟","answer":"الجواب: أما المسجد الحرام الذي حول الكعبة، فالمعروف عند أهل العلم: أنه لا حرج في المرور بين يديه للحاجة؛ لأن الغالب هو الزحمة فيه، ومظنة عدم تيسر السترة والسلامة من المار، فالأمر فيه واسع، وهكذا عند الازدحامات في المسجد النبوي وغيرها من المساجد، إذا ازدحم الناس وتكاثر الناس ولم يتيسر للمسلم المرور إلا بين أيدي المصلين، فالظاهر والله أعلم أنه لا حرج في ذلك للضرورة والمشقة الكبيرة. \nوينبغي للمصلي أن يتحرى المكان الذي ليس فيه تعرض للمرور بين يديه، في لزوم السواري التي في المسجد وأشباهها حتى يكون بعيداً عن المرور بين يديه، أما مساجد مكة وأرضها فالظاهر أنها كغيرها، ولهذا لما صلى النبي صلى الله عليه وسلم بالأبطح جعل أمامه العنزة، وصلى إلى عنزة عليه الصلاة والسلام وهو في الأبطح في المسجد الحرام، فدل ذلك على أن المسجد الحرام مثل غيره في اتخاذ السترة، يعني بقية الحرم؛ لأن الحرم كله يسمى مسجد حرام، لكن ما كان حول الكعبة فالأمر فيه أوسع وأسهل للزحمة غالباً، ولما جاء في ذلك من الآثار عن بعض الصحابة في عدم توقي مرور الناس؛ لأنه موضع زحمة في الغالب، مظنة عدم القدرة على السلامة من المار؛ ولأن في السترة ورد الناس مشقة على الطائفين وعلى غير الطائفين، فالأولى والأقرب والأرجح أنه لا حرج في ذلك إن شاء الله، ولا لزوم للسترة، لكن في بقية مكة في بقية الحرم ويسمى المسجد الحرام ينبغي اتخاذ السترة ومنع المار كما اتخذها النبي صلى الله عليه وسلم في الأبطح عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4677/ما-حكم-المرور-بين-يدي-المصلي-في-المسجد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02407.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":8087,"question":"أولى رسائل هذه الحلقة رسالة وصلت من أحد الإخوة المستمعين يقول: (ن. م. أ. ن) -صاحب الرسالة يعقب على حلقة مضت من حلقات هذا البرنامج- يقول: لقد استمعت إلى الحلقة المقدمة من هذا البرنامج، حيث تكرم فضيلة الشيخ عبد العزيز بن باز بالإجابة على أسئلة المستمعين، وكان من ضمن إجاباته عن أحد الأسئلة عن مرور الكلب الأسود والمرأة من أمام المصلي ثم ذكر أن ذلك يقطع الصلاة، أرجو منكم التكرم بسؤال فضيلة الشيخ عن طبيعة هذا المرور، هل إذا صلى الرجل واضعاً سترة أمامه ومرت المرأة من خلف السترة، هل يجب عليه أن يعيد الصلاة؟ ثم ما حكم مرور النساء أمام الرجال في أوقات الزحام ولا سيما في الحرمين، أرجو التفضل بالإجابة ولكم الشكر؟","title":"حكم مرور المرأة بين يدي المصلي في الحرم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد سبق في هذا البرنامج غير مرة بيان حكم المرور بين يدي المصلي وأن الرسول ﷺ قال: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل المرأة والحمار والكلب الأسود خرجه الإمام مسلم في صحيحه من حديث أبي ذر ، وخرج معناه من حديث أبي هريرة  لكن بدون ذكر الأسود، وخرجه أيضاً أبو داود والنسائي وجماعة من حديث ابن عباس مرفوعاً وذكر فيه قيد المرأة بالحائض.\nفتلخص من هذه الأحاديث وما جاء في معناها أن الذي يقطع الصلاة واحد من هذه الثلاثة: المرأة البالغة وهي التي حاضت يعني: التي قد بلغت الحلم بخلاف الصغيرة، والحمار مطلقاً بجميع أنواعه وهو الحمار الأهلي الذي يستعمله الناس سابقاً في جلب الماء والركوب والتحميل، والثالث: الكلب الأسود.\nقيل: يا رسول الله! ما بال الأحمر والأصفر من الأسود؟ قال: إن الكلب الأسود شيطان، فدل ذلك على أن هذا مختص بهذه الثلاث وأنها إذا مرت بين المصلي وبين سترته قطعت عليه صلاته، سواء كانت نافلة أو فريضة، إذا كان مرورها بين الرجل أو المرأة وبين السترة.\nوأما إذا كان مرورها وراء السترة من أمامها من جهة القبلة فإنها لا تقطع، إذا مرت هذه الثلاث أمام السترة فإنها لا تقطع وإنما تقطع إذا كانت بينه وبين السترة من داخل فإنها تقطع عليه صلاته، وهكذا لو مرت بعيدة، إذا كان ما عنده سترة ومرت بعيدة عنه فوق ثلاثة أذرع من قدمه فإنها لا تقطع، وإنما تقطع في حدود ثلاثة أذرع فأقل من قدم المصلي إذا لم يكن لديه سترة، وهذا هو الصحيح من أقوال أهل العلم، وفي المسألة خلاف: بعض أهل العلم يقول: إنها لا تقطع وإنما تقطع الكمال فقط والصلاة صحيحة، لكنه قول ضعيف، وكلام الرسول ﷺ واضح في أنها تقطع، والأصل أنها تقطع -أي: تبطل- هذا هو الصواب وهذا هو المعتمد.\nأما في حال الزحام الذي لا حيلة للمصلي كما يقع في المسجد الحرام فإنها لا تقطع، مرور المرأة في المسجد الحرام بين الناس في المطاف أو في غيره لا تقطع عند عامة أهل العلم، وحكاه بعض أهل العلم إجماعاً لأن التحرز من ذلك فيه صعوبة وغير ممكن في الأغلب، فهذا من رحمة الله  أن مرور النساء في المسجد الحرام في المطاف أو في غيره لا يقطع، هذا هو الصواب وقد حكاه بعض أهل العلم إجماعاً، والحكمة في ذلك واضحة وهي: أن التحرز من ذلك متعسر أو متعذر، فمن رحمة الله أن رفع هذا الحكم، وقد جاء فيه بعض الأحاديث التي فيها بعض المقال وفعل بعض الصحابة ذلك، كان ابن الزبير يصلي والنساء أمامه في المطاف ولا يتأثر بذلك؛ لعلمه بأنهن لا يقطعن، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/5879/حكم-مرور-المراة-بين-يدي-المصلي-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_101/10101.mp3","categories":["سترة المصلي"]},{"id":8207,"question":"أخونا يسأل سؤال آخر ويقول: سمعت من أحد العلماء أن هناك ثلاثة أشياء تبطل الصلاة، وهي: مرور الكلب الأسود أمام المصلي، ومرور المرأة الحائض وأيضاً الحمار، فهل هذا الكلام صحيح مع الدليل إذا كان صحيحاً؟","title":"بيان ما يقطع صلاة المصلي بالمرور أمامه","answer":"الجواب: نعم صحيح، رواه مسلم في صحيحه رحمه الله عن أبي ذر رضي الله عنه عن النبي ﷺ أنه قال: يجزئ أحدكم في الصلاة أن يكون بين يديه مثل مؤخرة الرحل، فإذا مر بينه وبينها المرأة والحمار والكلب الأسود ..... صلاته، وفي اللفظ الآخر: يقطع صلاة المرء المسلم المرأة والحمار والكلب الأسود، خرجه مسلم في الصحيح، وخرجه أيضاً من حديث أبي ذر ، وليس فيه ذكر الأسود، ولكن قاعدة الشرع: أن الحديث المطلق يقيد بالمقيد، فلهذا قال له أبو ذر يا رسول الله! ما بال الأسود من الأحمر والأصفر؟ قال: الكلب الأسود شيطان، بين ﷺ أنه شيطان جنسه، وأن الأسود هو شيطان هو جنس الكلاب، فيقطع الصلاة دون بقية الكلاب، والحمار كذلك مطلقاً، وأما المرأة فجاء في حديث ابن عباس عند أبي داود والنسائي بإسناد جيد تقييدها بالحائض، فيكون رواية ابن عباس مقيدة لرواية أبي ذر وأبي هريرة ، وأنها المرأة البالغة يعني، التي قد بلغت المحيض، مثل ما في الحديث الآخر، يقول ﷺ: لا يقبل الله صلاة المرأة الحائض إلا بخمار. فقال: فالحائض لها شأن وهي التي قد بلغت الحلم، وصارت المحل الشهوة للرجال، والصغيرة لا تقطع الصلاة، وإنما تقطعها المرأة التامة البالغة التي قد بلغت المحيض، هذه الثلاث تقطع الصلاة، وقد أشكل هذا على عائشة رضي الله عنها وقالت: بئس ما شبهتم بنا بالحمير والكلاب؟ لقد كنت أعترض بين يدي النبي ﷺ على السرير وهو يصلي وهذا الذي قالته رضي الله عنها حسب اجتهادها، مع كونها من أفقه النساء، ولكن يخفى عليها أشياء، وهذا مما خفي عليها، فإن كونها على السرير كونها مضطجعة بين يدي النبي ﷺ ليس بمرور، المرور هو الذي يقطع، أما كونها مضطجعة أمام المصلي، أو جالسة أمام المصلي، هذا ليس بمرور ولا يقطع الصلاة، وإنما الذي يقطعه المرور، فـعائشة رضي الله عنها خفي عليها هذا الأمر، وكلام النبي ﷺ مقدم عليها وعلى غيرها، فهو المشرع والمعلم عليه الصلاة والسلام. فالواجب طاعة أمره واتباع شريعته، وإفهام النساء وغير النساء مراده عليه الصلاة والسلام.\nالمقدم: جزاكم الله خيراً، شيخ عبد العزيز ! لا أدري هل هناك فرق بين المرأة إذا مرت أمام محرمها أو إذا مرت المرأة أمام رجل يصلي وهو من غير محارمها؟\nالجواب: لا فرق في ذلك، إذا مرت المرأة بين يدي المصلي، سواء كان المصلي محرماً لها أو أجنبياً أو امرأة أيضاً، حتى ولو كانت امرأة، إذا مر الحمار والكلب والمرأة بين يدي المصلي رجلاً أو امرأة، قريباً أو بعيداً، زوجاً أو غير زوج، كلهم، الحديث عام يعم الجميع.\nالمقدم: هل بينت الحكمة كما بينت في الكلب شيخ عبد العزيز؟\nالجواب: ما أذكر شيء في هذا.\nالمقدم: لعله يبحث هذا الموضوع سماحة الشيخ ولاسيما أن الكثيرين يثيرون حوله أكثر من سؤال؟\nالشيخ: القاعدة التي عليها أهل العلم تلقي ما قاله النبي ﷺ بقلب منشرح وصدر رحب، سواء علمنا الحكمة أو لم نعلم الحكمة، لأننا نقطع ونجزم أن ربنا حكيم عليم، وأنه لا يأمر إلا لحكمة، ولا ينهى إلا عن حكمة، فقد تظهر لمؤمن قد تظهر لطالب العلم وقد تخفى، وقد يخفى بعضها ويظهر بعضها، فمن ظهرت له الحكمة هذا نور على نور فضل من الله، وإن لم تظهر الحكمة فليس له أن يعترض، عليه أن يتبع، وأن يلتزم بأمر الله، ولا يقول في الحكمة، فهذه الصلاة الآن الظهر أربع والعشاء أربع والعصر أربع، والمغرب ثلاث، والفجر ركعتان، فقد يتنازع الناس في الحكمة ما هي الحكمة في هذا؟! وربك هو الحكيم العليم ، وإذا قال أحد: إن الظهر أو العصر أو العشاء وقت مناسب للطول، فقد يقول آخر: الفجر أنشط وأقوى في حق من نام مبكراً فهو أنشط على أن يصلي أربعاً الفجر، وأنشط أن يصلي صاحب المغرب ثلاثاً إذا كان مستريحاً العصر أو مستريحاً الظهر والعصر. فالحاصل: أن هذا لا ينبغي أن يعتبر به، بل علينا التسليم والانقياد، وطاعة الله ورسوله في ذلك. وهكذا في الصيام، قد يقول القائل: ما الحكمة في جعل رمضان ثلاثين، صيام رمضان في الشتاء والصيف، في الشتاء برد وفيه مشقة، في القيام فيه مشقة لو جعل القيام ليلة خمسة عشر وفي الشتاء ثلاثين، كل هذه تخرصات ليس للعبد أن يقولها، بل عليه يرضى ويسلم ويقبل شرع الله، وهكذا في الحج، وقد يقع في وقت الشتاء، وقد يقع في وقت الصيف، وفيه مشاق، ومع هذا الله نظمه في وقت معين سبحانه وتعالى، فعلينا أن نتبع ونسلم لأمر الله، ونخضع لحكمه سبحانه، وإذا بين لنا شيئاً من الحكم فهذا فضل منه، فضل منه سبحانه. نعم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء، عسى أن تتاح لنا فرصة أخرى سماحة الشيخ لتتفضلوا بمزيد من الإيضاح حول هذا الموضوع. الشيخ: إن شاء الله. المقدم: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/6027/بيان-ما-يقطع-صلاة-المصلي-بالمرور-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09513.mp3","categories":["سترة المصلي"]},{"id":8596,"question":"شيخ عبد العزيز، أمامي مجموعة من الأسئلة تتعلق بالصلاة:السؤال الأول: ما حكم المرور بين صفوف المصلين حتى يجد المار مكانًا يصلي فيه؟","title":"حكم المرور من بين يدي المأموم في الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا حرج أن يمر المسلم بين المصلين والإمام يصلي ليلتمس مكاناً إذا لم يجد طريقاً سوى ذلك، أما إذا وجد طريق بحيث يذهب معه حتى يتصل بآخر الصفوف فالأولى به أن يذهب مع الطريق حتى لا يشوش على أحد، أما لو احتاج إلى ذلك فلا بأس؛ لأن المأموم لا يضره مرور من مر بين يديه؛ لأنه مربوط بصلاة الإمام فلا يضره من مر بين يديه.\nوفي الصحيحين عن ابن عباس رضي الله تعالى عنهما قال: أتيت إلى النبي ﷺ وهو يصلي في منى وأنا على أتان، فنزلت عنها ودخلت في الصف وتركت الأتان ترتع يعني بين الصفوف، فلم يضر ذلك صلاتهم؛ لأنهم محكومون بحكم الإمام، سترة الإمام سترة لهم، فلا يضرهم مرور الأتان -يعني: الحمار- أو مرور إنسان آخر، لكن إذا تيسر أن يكون مرور الإنسان أو دابته من جهة أخرى حتى لا تشوش على الصفوف فهذا هو الأولى.\nولعل السبب في مرور أتان ابن عباس عدم تيسر طريق لها ذاك الوقت حتى مرت من بين يدي بعض الصفوف. نعم.","link":"https://binbaz.org.sa/fatwas/6708/حكم-المرور-من-بين-يدي-الماموم-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12901.mp3","categories":["سترة المصلي"]},{"id":9215,"question":"هل يجب أن أعيد الصلاة أو أقطعها إذا مر أحد أمامي مع تعذر وضع السترة، وما هو الارتفاع المعتبر للسترة، وما هو تقدير المسافة التي لا يأثم المار بمروره على المصلي؟","title":"السترة وبيان ما يقطع الصلاة","answer":"الجواب: أما إن كان سترة فإنه يحرم المرور بين المصلي وبين السترة، إذا وضع كرسياً أو شيئاً آخر كحجر أو متكأ من المتكآت أمامه فإنه ليس لأحد أن يمر بينه وبين السترة، وإذا مر بينه وبين السترة حمار أو كلب أسود أو امرأة بالغة بطلت صلاته؛ لأنه صح عن النبي ﷺ أنه قال: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة والحمار والكلب الأسود. قيل: ياا رسول الله! ما بال الأسود من الأصفر والأحمر؟ قال: الكلب الأسود شيطان رواه مسلم في الصحيح، وله شواهد من حديث أبي هريرة وابن عباس.\nوالسترة تكون نحو ثلثي ذراع تقريباً؛ لأن الرسول ﷺ قال: إذا لم يكن بين يديه مثل مؤخرة الرحل ومؤخرة الرحل: هي العود الذي يكون خلف ظهر الراكب في السدال الذي كانوا يستعملونه في الإبل وهو نحو ثلثي ذراع، فإذا كانت السترة نحو ثلثي ذراع أو أكثر كعصاً تركز، أو مركاً يجعل أمامه، أو حجراً كبير أو كرسي أمامه أو نحو ذلك فإن هذا يقال له: سترة، فينبغي أن تكون قريباً منه حول موضع سجوده، والمسافة التي تكون مانعة من القطع ثلاثة أذرع، فإذا كان المار أمامها وليس هناك سترة لم يقطع؛ لأنه ﷺ صلى لما فتح الله عليه مكة صلى في الكعبة وجعل بينه وبين الجدار الغربي ثلاثة أذرع، قالوا: فهذا يدل على مقدار ما بين رجلي المصلي ومحل السترة، فإذا كان الذي أمام المصلي أكثر من ثلاثة أذرع ومر مار أمامه فإنه لا يقطع صلاته ولا يحرم على المار، أما إن كان أقل من ثلاثة أذرع فإنه يقطع يسمى ماراً بين يديه، أو كان بينه وبين السترة فإنه يقطع إذا كان من الثلاثة؛ المرأة.. الحمار.. الكلب الأسود، أما إن كان من غير الثلاثة كمرور الرجل، مر رجل أو مر كلب غير أسود، أو مرت دابة كالإبل شاة بقرة ونحو ذلك هذا لا يقطع كلها لا تقطع، لكن ما ينبغي المرور، يمنع المرور؛ لأن الرسول ﷺ أمر بمنع المار قال ﷺ: إذا كان أحد يصلي إلى شيء يستره من الناس فلا يدع أحد يمر بين يديه.\nفالمقصود أنه يلاحظ منع المار حتى لا يشوش عليه صلاته ولو كان غير الثلاثة، ولو كان رجل، ولو كان بهيمة، يحاول أن لا تمر حتى لا تشوش عليه صلاته، وربما غلبه المار فلا يقطع صلاته، كالرجل غلبه ومر أو دابة غلبته أو صبي غلب ومر ما يضر صلاته صلاته صحيحة، إلا إذا كان المار امرأة أو حماراً أو كلباً أسود بينه وبين السترة أو في الثلاثة الأذرع يعني قريباً منه إذا لم يكن هناك سترة، هذا هو ملخص ما دلت عليه الأحاديث عن رسول الله عليه الصلاة والسلام. نعم.\nالمقدم: سماحة الشيخ! لعله من المناسب أن تتفضلوا بإيضاح ذلك الإشكال الذي أشكل على إحدى الصحابيات إن لم تكن من إحدى أمهات المؤمنين حينما ألحقت المرأة بالكلب الأسود وبالحمار، لعل لهذا المقام مناسبة في أن توضحوا هذا لو تكرمتم؟\nالجواب: نعم، جاء عن عائشة رضي الله عنها أم المؤمنين أنها لا ترى أن المرأة تقطع وخفي عليها الحديث وقالت: بئس ما شبهتمونا بالحمير والكلاب، كنت أضطجع بين يدي رسول الله ﷺ وهو يصلي فظنت رضي الله عنها أن اضطجاعها مثل المرور، وليس الأمر كذلك عند أهل العلم.\nقال العلماء: المرور شيء واضطجاعها أمامه ﷺ شيء آخر، فلو كانت المرأة مضطجعة على سريرها أو في الأرض وصلى إليها لا بأس لا حرج كان يصلي إليها وهي أمامه عليه الصلاة والسلام لا حرج في ذلك ولا تقطع صلاته إنما القطع بالمرور من جانب إلى جانب، فإذا مرت من جانب إلى جانب أمامه بينه وبين السترة أو في أقل من ثلاثة أذرع في الثلاث الأذرع هذا هو محل القطع، أما الحكمة فالله أعلم ما هي الحكمة الذي جعلت المرأة تلحق بالحمار والكلب الأسود الله أعلم سبحانه وتعالى، ويمكن أن يقال: إن الحكمة في ذلك أن المرأة تتعلق بها نفوس الرجال وميول الرجال وشهوات الرجال فربما يكون مرورها سبباً ...... نفس المصلي وتحرك قلبه لشيء مما يتعلق بالنساء فكان مرورها قاطعاً للصلاة حتى يمنع مرورها منعاً باتاً حتى لا يتساهل في ذلك، متى علم أن مرورها يقطع صار ذلك من أسباب منع المرور وقطع هذه المادة، يمكن أن يقال هذا والله أعلم، الحكمة قد تظهر وقد لا تظهر ولكن المسلمون مأمورون بأن يتلقوا أحكام الله ويقبلوها ويعملوا بها وإن لم يعرفوا حكمتها، مع الإيمان بأن ربنا سبحانه حكيم عليم، كما قال : إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا [النساء:11]، إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ [الأنعام:83]، هكذا في آيات كثيرات يعلم عباده أنه حكيم فيما يشرع من مواريث ومن صلوات ومن غير ذلك، كما أنه حكيم فيما يقدره على العباد من مرض أو موت أو غنى أو فقر أو حرب أو سلم أو غير ذلك، هو الحكيم العليم سبحانه في كل شيء وإن لم يطلعنا على الحكمة في بعض المسائل، وإن لم نعرف الحكمة ولم تتضح لنا فعلينا أن نؤمن بأنه حكيم عليم وإن لم نعرف تلك الحكمة، كما أنه سبحانه شرع الفجر ثنتين والمغرب ثلاثاً والظهر والعصر والعشاء أربعاً فما هي الحكمة؟ الله أعلم. لماذا جعل المغرب ثلاثاً؟ ولماذا جعل الفجر ثنتين والجمعة ثنتين؟ ولماذا جعل الظهر والعصر والعشاء أربعاً؟ ولماذا جعل الصيام في رمضان لا في غيره كالمحرم وكرجب، ولماذا جعله شهراً بدون زيادة؟ وقد تظهر الحكمة في عدم الزيادة أنه تخفيف ورحمة من الله، لكن كونه جعله في هذا الوقت المعين بين شوال وبين شعبان، الله هو الذي يعلم الحكمة سبحانه وتعالى، كذلك كونه شرع الزكاة في مال دون مال لحكمة بالغة قد تظهر للعباد وقد لا تظهر للعباد.. إلى غير ذلك من المسائل التي قد تخفى فيها الحكمة على الناس لكن يجب الإيمان بأنه حكيم عليم، وهكذا في المخلوقات قد يقول قائل: لماذا خلق الذباب؟ لماذا خلق الخنفساء؟ لماذا خلق العقرب؟ لماذا خلق الحية؟ لماذا خلق أشياء أخرى؟ نقول: إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ [الأنعام:83]، هو الخلاق العليم وهو الحكيم العليم؛ لحكمة بالغة خلق هذه الأشياء سبحانه وتعالى، ومن ذلك: أن يعلم أنه على كل شيء قدير، وأن ما شاء فعل لا راد لقضائه ولا راد لأمره سبحانه وتعالى، فهكذا يقال في بقية الأمور التي تخفى حكمتها ككون المرأة تقطع الصلاة. نعم.\nالمقدم: بارك الله فيكم، إذاً لا داعي للمناقشة، لا داعي للتأثر، لا داعي لفتح الباب أمام أولئك الذين يثيرون الشبه؟\nالشيخ: ليس هناك داعي نحن عبيد، عبيد مأمورون علينا أن نمتثل أمر الله وأن نترك نهيه سبحانه وتعالى؛ لأنه ربنا وإلهنا والمنعم علينا وخالقنا ورازقنا، وهو أعلم بمصالحنا من أنفسنا، فعلينا أن نسلم لأمره ولا نعترض، أرأيت لو كان إنسان عند مالك له من أبناء الدنيا من الناس فقال لمالكه إذا أمره: أنا لا أمتثل حتى تبين لي مقصدك من هذا الأمر! قال له سيده: هات لنا البعير الفلاني، هات لنا الإناء الفلاني، هات لنا الشاة الفلانية، هات لنا البساط الفلاني، إذا قال المملوك: أنا لا آتي به حتى تعلمني ويش القصد ما هي الحكمة، فهل يكون هذا العبد مرضياً عليه؟ وهل يكون هذا العبد أديباً؟ ليس بأديب ولا مرضي عليه، بل ربما ضربه سيده وربما باعه بأرخص الأثمان؛ لأنه ليس بأديب، فالواجب أن يمتثل ما قاله سيده وأن يحضره إلا إذا كان شيء يضره أو فيه معصية لله هذا شيء آخر محل بحث، لكن في الجملة الخادم والعبد يمتثل ما يستطيعه وما لا يعلم فيه معصية لله سبحانه وتعالى، فإذا كان العبد للعبد؛ الخادم للعبد لو اعترض يكون سيئ الخلق وسيئ الأدب فكيف بالعبد مع ربه الخلاق العليم؟ العالم بمصالح العباد، كيف يعترض وكيف يقول يعني بلسان حاله: أنا ما أمتثل حتى أعرف ويش حكمة الصوم، ويش حكمة الصلاة، ويش حكمة مروري على أمام كذا، ويش حكمة طوافي، ويش حكمة شربي قائماً أو قاعداً إلى آخر هذا؟ لا.من الأدب ومن العبودية ومن القيام بالواجب أن يمتثل وأن لا يقف عند مراعاة الحكمة. نعم.\nالمقدم: رضينا بالله رباً وبالإسلام ديناً وبمحمد صلى الله عليه وسلم نبيًا ورسولاً.","link":"https://binbaz.org.sa/fatwas/7376/السترة-وبيان-ما-يقطع-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_152/15205.mp3","categories":["سترة المصلي"]},{"id":9708,"question":"تقول السائلة سماحة الشيخ: عندما أقف للصلاة يقف أولادي الصغار أمامي وأنا أصلي، هل تبطل صلاتي وهم صغار سنتين وثلاثة أشهر تقريباً؟","title":"حكم صلاة المرأة إذا كان بين يديها أولادها الصغار","answer":"","link":"https://binbaz.org.sa/fatwas/7858/حكم-صلاة-المراة-اذا-كان-بين-يديها-اولادها-الصغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27207.mp3","categories":["سترة المصلي"]},{"id":9709,"question":"تقول السائلة سماحة الشيخ: عندما أقف للصلاة يقف أولادي الصغار أمامي وأنا أصلي، هل تبطل صلاتي وهم صغار سنتين وثلاثة أشهر تقريباً؟","title":"حكم صلاة المرأة إذا كان بين يديها أولادها الصغار","answer":"","link":"https://binbaz.org.sa/fatwas/7858/حكم-صلاة-المراة-اذا-كان-بين-يديها-اولادها-الصغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27207.mp3","categories":["سترة المصلي"]},{"id":9875,"question":"أيضًا في رسالة السائلة (س. م. أ) من دولة الكويت والتي ذكرنا سؤالها عن الحلي، في رسالتها عدة أسئلة من ضمنها تقول: كنت أصلي المغرب فمر بين يدي أرنب فهل تنقطع صلاتي بذلك؟","title":"بيان ما يقطع الصلاة بالمرور أمام المصلي","answer":"الجواب: مرور أرنب أو غيرها من الحيوانات بين يدي المصلي لا يقطع الصلاة، الأرنب والعنز وغير ذلك من الحيوانات لا تقطع الصلاة إنما يقطعها أحد ثلاثة أشياء على الصحيح من أقوال العلماء: المرأة البالغة، والكلب الأسود خاصة، والحمار. هكذا جاء عن النبي ﷺ أنه قال : يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة والحمار والكلب الأسود، قيل: يا رسول الله! ما بال الأسود من الأحمر والأصفر؟ قال: الكلب الأسود شيطان.\nفالمقصود أن هذه الثلاث هي التي تقطع على الصحيح من أقوال العلماء، فيه خلاف بين أهل العلم ولكن الصحيح من أقوال أهل العلم هو هذا، أنه لا يقطع الصلاة إلا واحد من هذه الثلاثة: إما المرأة وإما الحمار مطلقًا وإما الكلب الأسود بهذا القيد، أما بقية الحيوانات كالكلب غير الأسود وكالبعير والعنز والأرنب والقط أو غير ذلك فهذه كلها لا تقطع الصلاة، ولكن إذا تيسر أنها لا تمر إذا حاول أنها لا تمر يكون أولى، لا يدع شيئًا يمر بين يديه، وهكذا مرور الرجل بين يدي المصلي لا يقطع الصلاة ولكن ينقص ثوابها فينبغي أنه يمنع من المرور إذا أمكن ذلك، ولا يجوز المرور بين يدي المصلي، النبي ﷺ نهى عن المرور بين يدي المصلي وقال: لو يعلم المار بين يدي المصلي ماذا عليه لكان أن يقف أربعين خيرًا له من أن يمر بين يدي المصلي وأمر من كان يصلي شيء يستره من الناس أن لا يدع أحد يمر بين يديه بل يمنعه، فقال ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس فأراد أحد أن يجتاز بين يديه فليدفعه، فإن أبى فليقاتله فإنما هو شيطان فالسنة تدل على أن المصلي يمنع المار بين يديه ولو كان غير واحد من الثلاثة ولو كان غير الكلب وغير المرأة وغير الحمار لا يدع شيئًا يمر بين يديه لا إنسان ولا حيوان آخر إذا تيسر له ذلك، أما إذا غلبه ومر فإنه لا يضر صلاته، لكن يضر صلاته ويقطعها واحد من الثلاثة: إما الكلب الأسود، وإما المرأة، وإما الحمار، هذه الثلاث تقطع للحديث الصحيح الذي سبق ذكره وهو قوله ﷺ: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة والحمار والكلب الأسود.\nوالسنة للمؤمن إذا أراد أن يصلي يكون بين يديه شيء إما كرسي أو حربة يركزها في الأرض أو جدار أو عمود من العمد يصلي إليه حتى لا يمر بين يديه ما يقطع صلاته، فإذا مر المارون من وراء السترة لم يضروا الصلاة، إذا مروا من ورائها لم يضروا الصلاة، أما مرورهم بين يديه وبين السترة فهذا هو الذي يمنع، وإذا كان المار امرأة أو حمارًا أو كلبًا أسود قطع الصلاة، وهكذا إذا مر هؤلاء بين يديه قريب منه إذا كان ما عنده سترة، إذا كان ما جعل سترة إذا مروا قريبًا منه في خلال ثلاثة أذرع فأقل فإنها تقطع هذه الثلاثة، وإذا مروا بعيدين فإن ذلك لا يضر إذا كان المار بعيدًا فوق الثلاثة الأذرع فإنه لا يضر ؛ لأنه ﷺ صلى في الكعبة وجعل بينه وبين الجدار الغربي ثلاثة أذرع، احتج العلماء بهذا على أن هذه هي النهاية لمحل السترة،وأن السترة تكون من ثلاثة أذرع فأقل، فإذا كان الشيء أبعد من ذلك لم يضر المرور فيه، وهكذا إذا كانت السترة موجودة لا يضر ما مر من ورائها. نعم.\nالمقدم: طيب يا سماحة الشيخ! ما المقصود بالقطع الذي ذكرتم أن الثلاثة تقطع الصلاة؟\nالشيخ: إبطالها، إبطال الصلاة.\nالمقدم: وعليه إعادتها؟\nالشيخ: الجمهور يقولون: يقطع الكمال فقط، ولكن الصواب أنه يقطع الصلاة وعليه إعادتها إذا كانت فريضة يلزمه أن يعيدها.\nالمقدم: إذًا إذا مر واحد من هذه الثلاثة فعليه إعادة الصلاة فيما بينه وبين السترة؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8035/بيان-ما-يقطع-الصلاة-بالمرور-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19903.mp3","categories":["سترة المصلي"]},{"id":9882,"question":"أخيراً تقول هذه السائلة: إذا كنت أصلي داخل البيت أو داخل الغرفة، فإن سرير أختي وهي نائمة عليه يكون في جهة القبلة أي: أنني أستقبلها، فهل في هذا شيء أفيدوني أفادكم الله.","title":"حكم صلاة الإنسان وأمامه نائم","answer":"الجواب: لا حرج في ذلك أن يصلي الإنسان وأمامه نائم، كان النبي ﷺ يصلي وأمامه عائشة معترضة فلا بأس بهذا، لا حرج في ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8049/حكم-صلاة-الانسان-وامامه-ناىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26406.mp3","categories":["سترة المصلي"]},{"id":10325,"question":"ما حكم اتخاذ السترة بالنسبة للمصلي؟ وإذا كان المصلي يأمن من عدم مرور أحد بين يديه كأن يكون في صحراء مثلاً، فما حكم اتخاذ السترة بالنسبة له؟","title":"حكم السترة للمصلي","answer":"الجواب: اتخاذ السترة سنة، كان النبي يتخذ السترة حتى في الصحراء عليه الصلاة والسلام وهو مسافر، فالسنة اتخاذ السترة وهي مقدار مؤخرة الرحل، نحو ذراع أو ما يقارب ذراع تنصب أمامه، مثل الكرسي مثل العصا تنصب مثل شداد الرحل، مثل الإناء يجعل أمامه يبلغ ساق ذراع أو ذراع إلا ربع أو ما حول ذلك؛ لقوله ﷺ: يكفي أحدكم مثل مؤخرة الرحل، وفي لفظ آخر: إذا كان بين يدي أحدكم مثل مؤخرة الرحل فإنه يقطع صلاته: المرأة والحمار والكلب الأسود، يعني: إذا مر دونها.\nفالمقصود: أنه إذا كانت السترة نحو ذراع أو ما يقاربه فإن ما يمر بين يديه لا يضر صلاته إذا مر من وراء ذلك، أما إذا مر بينه وبين السترة فإنه يقطع صلاته: المرأة والحمار والكلب الأسود كما ثبت به الحديث عن النبي ﷺ: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة والحمار والكلب الأسود هكذا صح عنه عليه الصلاة والسلام.\nأما إذا كانت السترة جدار أو عمود فإنه يكفي بذلك، إذا مر بين يديه وبين السترة أحد يمنعه؛ لقوله ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس، فأراد أحد أن يجتاز بين يديه فليدفعه فإن أبى فليقاتله فإنما هو شيطان متفق على صحته، ولو كان المار ليس حماراً ولا كلباً ولا امرأة، حتى الرجل يمنع وحتى الصبي يمنع حتى الدابة تمنع من الغنم وغيرها إذا تيسر المنع، يمنع ذلك إذا تيسر، فإن غلبه لم يضر صلاته، إذا غلبه المار لم يضر صلاته إلا أن يكون حماراً أو كلباً أسود أو امرأة، يعني: تامة، امرأة تامة، أما الصبية لا تقطع الصغيرة لا تقطع، ولهذا في اللفظ الآخر: المرأة الحائض يعني: البالغة. نعم.\nالمقدم: جزاكم الله خيراً، إذا كان في الصحراء مثلاً أو أمن مرور أحد؟\nالشيخ: ولو أمن ولو أمن، السنة أن يتخذ السترة. نعم.","link":"https://binbaz.org.sa/fatwas/8498/حكم-السترة-للمصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31411.mp3","categories":["سترة المصلي"]},{"id":10790,"question":"سمعت من بعض الناس أنك إذا كنت تصلي، ولم تجعل أمامك خطًا، أو حاجزًا، ومر أحد ولو على بعد مائة متر أو أكثر فإنه يقطع صلاتك، وأنا لم أصدق بهذا أرجو توجيهي حول هذا الموضوع، جزاكم الله خيرًا.","title":"حكم المرور أمام المصلي بغير سترة","answer":"الجواب:  السنة للمؤمن والمؤمنة وضع السترة إذا أراد أن يصلي وهو مفرد أو إمام، يضع السترة أمامه، لقول النبي ﷺ: إذا صلى أحدكم فليصل إلى سترة، وليدن منها خرجه الإمام أبو داود -رحمه الله- بإسناد صحيح وغيره. فالسنة له أن يقرب من السترة، وأن تكون قائمة كالعصا، أو كرسي، أو يستقبل جدارًا، أو سارية، تكون سترة له، هذا هو السنة، وفي اللفظ الآخر يقول ﷺ: إذا صلى أحدكم فليجعل تلقاء وجهه شيئًا، فإن لم يجد فلينصب عصا، فإن لم يجد فليخط خطًا، ثم لا يضره من مر بين يديه. خرجه الإمام أحمد وابن ماجة بإسناد حسن. لكن لو صلى إلى غير سترة فإنه لا يمر بين يديه قريبًا منه، ولكن يمر بعيدًا، إذا كان المار بعيدًا أكثر من ثلاثة أذرع لا يضره ذلك؛ لأنه ﷺ لما صلى في الكعبة جعله بينه وبين الجدار الغربي ثلاثة أذرع، فدل ذلك على أن هذه المسافة كافية.  أما إذا كان له سترة فإنه لا يمر بين يديه وبين السترة، بل يمر من ورائها، ولكن لا يقطع الصلاة، المار إلا إذا كان أحد ثلاثة، إما امرأة، أو حمارًا، أو كلبًا أسود، هذه هي التي تقطع الصلاة، صلاة الرجل والمرأة جميعًا، لقوله ﷺ في الحديث الصحيح: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة والحمار والكلب الأسود قيل: يا رسول الله! ما شأن الأسود من الأصفر والأحمر؟ قال: الكلب الأسود شيطان وفي لفظ من حديث ابن عباس: المرأة الحائض يعني البالغة. أما الصبية التي لم تبلغ فلا تقطع، إنما يقطع المرأة الكاملة البالغة المكلفة إذا مرت تقطع، وهكذا الحمار، وهكذا الكلب الأسود، أما غيرهم فلا ينبغي مروره، يمنع من المرور، لكن لو مر وغلب لا يقطع الصلاة؛ لأن الرسول ﷺ خص القطع بهؤلاء الثلاثة، ومع ذلك ممنوع أن يمر بين يدي أخيه ولو كان رجلًا، فالمصلي يمنع المار بين يديه، سواء رجلًا، أو دابة، أو صبيًا، أو صبية، أو كلبًا، أو غير ذلك، ولو كان غير أسود، لقوله ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس فلا يدع أحدًا يمر بين يديه، فإن أبى فليقاتله فإنه شيطان وفي اللفظ الآخر: فأراد أحد أن يجتاز بين يديه فليدفعه، فإن أبى فليقاتله فإنه شيطان. الحاصل: أنه يمنع المار بالتي هي أحسن، فإذا لم يتيسر بالتي هي أحسن دفعه بالقوة من غير أن يتعمد قتلًا أو ضربًا يضره، ولكن يدفعه بالقوة التي تشعر المار بأن المصلي عازم على رده، وواصل دفعه بالصدق والقوة، لقوله ﷺ: فليقاتله يعني فليدفعه بالقوة، لكن لا يتعمد ضربه بالسلاح أو شيئًا يقتله، ولكن يدفعه بقوة حتى يرجع، ولا يمر بين يديه؛ لأن الرسول أمر بهذا -عليه الصلاة والسلام- والحديث صحيح أخرجه الشيخان البخاري ومسلم في الصحيحين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8969/حكم-المرور-امام-المصلي-بغير-سترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_351/35106.mp3","categories":["سترة المصلي"]},{"id":10883,"question":"نعود مع مطلع هذه الحلقة إلى رسالة إحدى الأخوات المستمعات من الرياض، رمزت إلى اسمها بالحروف (خ. أ. ع) تقول في أحد أسئلتها: علمت أن من السنة وضع السترة أمام المصلي، فهل يجوز وضع سترة قصيرة كأن يكون طولها شبرًا؟ وإن لم يصلح فما مقدار طولها؟","title":"حكم السترة ومقدارها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فاتخاذ السترة للمصلي سنة مؤكدة، كان النبي ﷺ يفعلها في أسفاره، وكانت تحمل معه العنزة، وهي عصا صغيرة لها حربة تركز أمامه -عليه الصلاة والسلام- ويصلي إليها، كان في المسجد يصلي إلى السترة، عليه الصلاة والسلام. فالسنة لكل مصلٍ من رجل، أو امرأة أن يصلي إلى سترة، ولهذا في الحديث الصحيح الذي رواه أبو داود وغيره عن أبي سعيد  عن النبي ﷺ أنه قال: إذا صلى أحدكم فليصل إلى سترة، وليدن منها السنة الدنو منها، ولما صلى في الكعبة -عليه الصلاة والسلام- دنا من الجدار الغربي حتى لم يكن بينه وبينه إلا ثلاثة أذرع. فالسنة للمؤمن والمؤمنة اتخاذ سترة كالجدار، أو السارية، أو الكرسي أمامه، أو ما أشبهه مما له جسم قائم، وأقل ذلك مثل مؤخرة الرحل، قال العلماء: وهي تقارب الذراع، أو ثلثي الذراع إذا كانت السترة القائمة نحو ثلثي الذراع، أو ما يقارب ذلك كفت إذا تيسر ذلك، فإن لم يتيسر صلى ولو إلى عصا مطروحة، أو خط كما في حديث أبي هريرة  عن النبي ﷺ أنه قال: إذا صلى أحدكم فليجعل تلقاء وجهه شيئًا، فإن لم يجد فلينصب عصا، فإن لم يجد فليخط خطًا، ثم لا يضره من مر بين يديه. فالمؤمن يجتهد، وهكذا المؤمنة، فإن وجد جدرًا صلى إليه، أو سارية، أو كرسيًا، أو مركى مما يتكأ عليه يجعله أمامه، أو عصا لها حربة يركزها في الأرض، أو ما أشبه ذلك مما يكون له قاع، أو له ظل قائم .... كذراع، أو ما يقاربه ثلثي ذراع، أو ما يقارب ذلك، فإن لم يتيسر له ذلك جعل وسادة أمامه، أو عصا مطروحة أمامه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] حسب التيسير، أو خطًا إذا كان في الأرض كالصحراء، ليس عنده شيء، خط خطاً ويكفي على الصحيح، والحديث لا بأس به، كما قال الحافظ ابن حجر: إسناده حسن، رواه ابن ماجة وأحمد وجماعة بإسناد حسن. فالحاصل: أن هذا الحديث الذي فيه الخط لا بأس به على الصحيح، وهو عند الحاجة، عند عدم تيسر الجدار والعصا المنصوبة يخط خطاً. وليست السترة واجبة، بل لو صلى إلى غير سترة صحت صلاته، لكن يكون ترك السنة، السنة أن يصلي إلى سترة، وإذا مر بين السترة وبين المصلي حمار، أو امرأة بالغة، أو كلب أسود قطع الصلاة، كما في الحديث الصحيح، يقول ﷺ: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل المرأة والحمار والكلب الأسود، في حديث ابن عباس: المرأة الحائض يعني: البالغة. وهذا يدل على أن الصغيرة لا تقطع، والرجل لا يقطع، وهكذا الإبل والغنم لا تقطع وسائر الدواب ما عدا الحمار.  وهكذا الكلاب كلها لا تقطع إلا الأسود، لكن لا ينبغي أن يمر شيء يمنع المار بين يديه، لا يمر شيء، للحديث الصحيح يقول ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس، فأراد أحد أن يجتاز بين يديه فليدفعه، فإن أبى فليقاتله، فإنما هو شيطان.  فإذا أراد شيء أن يمر بين يديك تدفعه ترده، ولو أنها شاة، أو طفلة ترده إذا تيسر ذلك، لكن لو مر لا يقطع، لا يفسد عليك صلاتك إلا إذا كان المار امرأة بالغة، أو حمارًا أو كلبًا أسود مر بين يديك قريبًا منك .. أقل من ثلاثة أذرع، أو بينك، وبين السترة ولو كان أكثر، إذا كان بينك وبين السترة، وأما ما مر من وراء السترة إذا مر من ورائها فإنه لا يضر، ولو كان المار كلبًا أسود، أو امرأة، أو حمارًا إذا كان من وراء السترة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9055/حكم-السترة-ومقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35901.mp3","categories":["سترة المصلي"]},{"id":11108,"question":"مستمع رمز إلى اسمه بالحروف (س. س. م) من خميس مشيط، أخونا له أكثر من سؤال عن السترة أثناء الصلاة، فيسأل في سؤاله الأول ويقول: ما حكم وضع السترة داخل المسجد وأمام المحراب؟ ما حكم صلاة من صلى إلى غير سترة داخل المسجد، وهل صلى الرسول ﷺ إلى سترة داخل المسجد آمل الإفادة، وتوضيح الأحاديث الدالة على ذلك؟ جزاكم الله خيرًا.","title":"ما حكم صلاة من صلى إلى غير سترة داخل المسجد؟","answer":"الجواب:  الصلاة إلى سترة سنة مؤكدة، وكان النبي ﷺ يصلي إلى سترة في المسجد وفي السفر، تنصب له العنزة، وفي المسجد يصلي إلى السترة التي وضعت له -عليه الصلاة والسلام- وهكذا المنفرد يصلي إلى سترة هذه السنة. أما المأموم يكفي سترة الإمام، ليس بحاجة إلى سترة، المأموم سترته سترة إمامه وهي سنة مؤكدة، لقوله -عليه الصلاة والسلام-: إذا صلى أحدكم فليصل إلى سترة، وليدن منها خرجه أبو داود بإسناد صحيح عن أبي سعيد . وقد ثبت عنه -عليه الصلاة والسلام- أنه في بعض الأحيان صلى إلى غير سترة، كما ذكر ذلك ابن عباس، وأخوه الفضل بن عباس فيما روى النسائي وغيره: أن النبي ﷺ زارهم في بعض الأحيان وصلى بهم إلى غير سترة، فدل على أنها ليست واجبة، وهكذا في الصحيحين من حديث ابن عباس: أنه أتى النبي ﷺ وهو يصلي في منى إلى غير جدار، ولم يقل: أن هناك سترة، فظاهره أنه صلى إلى غير سترة. فالمقصود: أن السترة سنة، ولو صلى إلى غير سترة الإمام، أو المنفرد فالصلاة صحيحة، ولكن الأفضل والسنة أن يجعل أمامه سترة إما جدار وإما كرسي وإما عمود وإما عصا ينصبها فإن لم يجد خط خطًا في الأرض، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9299/ما-حكم-صلاة-من-صلى-الى-غير-سترة-داخل-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36817.mp3","categories":["سترة المصلي"]},{"id":11881,"question":"عندما يصلي الإنسان، ويمر من أمامه شخص آخر، هل تنقطع صلاة المصلي في غير الحرمين؟","title":"الأشياء التي تقطع صلاة المرء بالمرور بين يديه","answer":"الجواب:  هذا فيه تفصيل: إن كان المار بين يديه، أو بينه وبين السترة امرأة، أو حمار، أو كلب أسود: انقطعت الصلاة؛ بطلت صلاته، فرضًا أو نفلًا، إذا كان المار بينه وبين السترة، إذا كان يصلي إلى جدار، أو إلى كرسي، أو إلى سترة أخرى، ثم مر بينه وبينها حمار، أو كلب أسود، أو امرأة؛ بطلت صلاته؛ لقوله ﷺ: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة والحمار والكلب الأسود. وهكذا إذا مرت بين يديه قريبة منه المرأة أو الحمار أو الكلب الأسود، إذا كان ما عنده سترة، ما له سترة، إذا مرت المرأة أو مر الحمار أو الكلب الأسود بين يديه في حدود ثلاثة أذرع، فأقل من قدمه؛ فإنها تبطل صلاته. أما إن كان بعيدًا، إن كان المار بعيدًا، ... ثلاثة أذرع، وليس هناك سترة؛ فإن الصلاة صحيحة، أو كان المار وراء السترة من خلفها ....... وراءها فالصلاة صحيحة، والحمد لله، أما إن كان المار غير الثلاثة، مر رجل أو كلب غير أسود، أو شاة، أو ما أشبه ذلك غير الثلاثة؛ فالصلاة صحيحة، وإن كان ينقص ثوابها، لكن الصلاة صحيحة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10065/الاشياء-التي-تقطع-صلاة-المرء-بالمرور-بين-يديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42502.mp3","categories":["سترة المصلي"]},{"id":12387,"question":"مستمع يقول المرسل (محمد . ع. ش) يقول: هل يجب على المصلي أن يمنع مرور الطفل من بين يديه في الصلاة؟","title":"حكم مرور الطفل بين يدي المصلي وما يقطع الصلاة","answer":"الجواب:  نعم لا يدع شيئًا يمر عليه، يمر بين يديه، يمنعه إذا تيسر ذلك، فإن غلبه؛ فلا شيء عليه، لكن يمنع إذا رأى الطفل، أو الدابة كالغنم ونحوها، يمنعها؛ إذا تيسر ذلك، فإن غلبه ذلك؛ فصلاته صحيحة، ولا يقطعها إلا ثلاثة: المرأة البالغة، والحمار، والكلب الأسود، إذا مر واحد من هذه الثلاثة بينه وبين سترته، أو قريبًا منه في حدود ثلاثة أذرع، فأقل؛ قطع عليه صلاته.  أما إن كان بعيدًا منه، أو فوق ثلاثة أذرع، أو كان وراء السترة؛ فإنه لا يقطع عليه الصلاة، أما غير الثلاثة؛ فإنه يمنع، لكن لا يقطع الصلاة مرور البعير أو الشاة أو الطفل أو الكلب غير الأسود، لو مر لا يقطع، لكن إذا أمكنه يمنعه يدفعه؛ فإنه يمنعه، لقول النبي ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس، فأراد أحد أن يجتاز بين يديه؛ فليدفعه، فإن أبى؛ فليقاتله، فإنما هو شيطان.  فهذا عام أمر فيه النبي ﷺ بدفع المار، سواء كان المار قاطعًا، أو ليس بقاطع، السنة والمشروع أن يدفعه، ويمنعه من المرور بالتي هي أحسن، فإن غلبه؛ صلاته صحيحة، إلا إذا كان المار كلبًا أسود، أو حمارًا، أو امرأةً مكلفة بالغة يعني: حائضًا، فإن الواحدة من هذه الثلاث يقطع بنص النبي -عليه الصلاة والسلام- نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10588/حكم-مرور-الطفل-بين-يدي-المصلي-وما-يقطع-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40107.mp3","categories":["سترة المصلي"]},{"id":12768,"question":"إذا مر بين يديك رجل، وأنت في أثناء الصلاة، فهل تبطل صلاتك؟","title":"مرور الرجل بين يدي المصلي","answer":"الجواب:  لا تبطل بمرور الرجل، مرور الرجل لا يبطل الصلاة، إنما يبطلها أحد ثلاثة: المرأة، والحمار، والكلب الأسود، كما قاله النبي ﷺ: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة، والحمار، والكلب الأسود أما إذا كان بين يديه سترة كعنزة، عصا مركوزة، أو عمود أمامه، أو كرسي أمامه، أو شبه ذلك، ومر وراءها امرأة، أو حمار، أو كلب أسود؛ فإنه لا يضر.  وهكذا لو مر بعيدًا منه، ليس بين يديه، مر بعيدًا أكثر من ثلاثة أذرع؛ فإنه لا يقطع الصلاة، أما الرجل فلا يقطع. وهكذا الكلب غير الأسود، وهكذا البعير والغنم لا تقطع، إنما يقطع هذه الثلاثة، المرأة يعني: البالغة، والحمار، والكلب الأسود كما جاءت السنة بذلك، ولكن لا ينبغي أن يمر بين يدي المصلي أحد، يمنع المار، يقول النبي ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس، فأراد أحدهم أن يجتاز بين يديه؛ فليدفعه، فإن أبى؛ فليقاتله، فإنما هو شيطان ويقول ﷺ: لو يعلم المار بين يدي المصلي ماذا عليه؛ لكان أن يقف أربعين خيرًا له من أن يمر بين يدي المصلي. فالمقصود: أن المصلي يمنع المار، ولو كان رجلًا، ولو كان حيوانًا يمنعه إذا استطاع، ولكن لا يقطع صلاته إلا أحد الثلاثة: المرأة، والحمار، والكلب الأسود، لكن يمنع الرجل أن يمر، يمنع الصبي أن يمر، يمنع العنز أن تمر، وهكذا إذا استطاع ذلك، للحديث الذي سمعت قوله ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس، وأراد أحد أن يجتاز بين يديه؛ فليدفعه فإن أبى؛ فليقاتله، فإنما هو شيطان نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10982/مرور-الرجل-بين-يدي-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41917.mp3","categories":["سترة المصلي"]},{"id":13703,"question":"يقول السائل أبو عابد في هذا  إذا صلى شخص في البر، أو الصحراء، ومر من أمامه كلب، لكنه ليس بأسود اللون، بل أي لونٍ آخر، فهل في هذه الحالة تبطل الصلاة، أم لا؟","title":"حكم صلاة من مر من أمامه كلب غير أسود","answer":"الجواب: لا تبطل إلا بالكلب الأسود؛ لقوله ﷺ: يقطع صلاة المرء المسلم: المرأة، والحمار، والكلب الأسود قيل: يا رسول الله! ما بال الأسود من غيره؟ قال: لأنه شيطان لكن لا يدع شيئًا يمر، يمنعه من المرور إذا تيسر، يمنع الكلب والحمار وغير ذلك؛ حتى لا يمر بين يديه إذا تيسر، يتقدم حتى يمروا خلفه، حتى لا يقطعوا صلاته، ولا يدع شيئًا يمر غير الثلاثة، كالرجل، أو الكلب غير الأسود، لا يدع شيئًا يمر، إذا تيسر يمنع المرور؛ لأنه يشوش عليه صلاته؛ لقوله ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس، وأراد أحد أن يجتاز بين يديه فليدفعه، فإن أبى فليقاتله فإنما هو شيطان. المقصود: أن الإنسان إذا صلى إلى شيء المشروع له ألا يدع أحدًا يمر بين يديه مطلقًا، لكن إذا مر بين يديه أحد الثلاثة: كلب أسود، أو حمار، أو امرأة بالغ قطع صلاته إلا إذا كان بعيدًا، أو من وراء السترة، كان من وراء السترة، أو بعيد، أكثر من ثلاثة أذرع فإنه لا يقطع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12075/حكم-صلاة-من-مر-من-امامه-كلب-غير-اسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53505.mp3","categories":["سترة المصلي"]},{"id":13851,"question":"رسالة من إحدى الأخوات المستمعات تقول في نهايتها: أختكم في الله تسأل هذا  هل السترة ضرورية في الصلاة؟ وهل السجادة تجزئ عنها؟","title":"هل السترة ضرورية في الصلاة؟ وهل السجادة تجزئ عنها؟","answer":"الجواب: السترة سنة، سنة مؤكدة في الصلاة؛ لقول النبي ﷺ: إذا صلى أحدكم فليصل إلى سترة وليدن منها مثل حائط أو عمود أو سارية أو كرسي أو ما أشبه ذلك، وقد جاء في الحديث الآخر عن النبي ﷺ أنه قال: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل المرأة والحمار والكلب الأسود والمؤخرة تقارب ذراع أو ذراع إلا قليل، فإذا جعل بينهم شيئًا منصوبًا من كرسي أو عصا أو شبه ذلك كما كان النبي ﷺ يفعل كانت تنصب أمامه العنزة وهي عصا ليست طويلة فيها حربة، فإذا فعل مثل ذلك المؤمن صارت سترة له أو كرسي قدامه أو وسائد رفيعة.. أو ما أشبه ذلك ولكن ليست بواجبة إنما هي سنة، فلو صلى بدون سترة صحت صلاته ولا حرج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12220/هل-السترة-ضرورية-في-الصلاة-وهل-السجادة-تجزى-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60216.mp3","categories":["سترة المصلي"]},{"id":13899,"question":"السائل عبدالهادي سوداني ومقيم في جدة يقول في هذا  نريد أن نعرف كل شيء حول السترة في الصلاة، وهل لا بد من وضع ساتر أمامي إذا كنت في الصلاة منفرداً ولا خوف من مرور أحد أمام المصلي؟","title":"حكم السترة وصفتها","answer":"الجواب: السترة سنة مؤكدة أمام المصلي إذا كان منفرداً أو إماماً؛ لأن الرسول كان يصلي إليها عليه الصلاة والسلام ويقول: إذا صلى أحدكم فليصل إلى سترة وليدن منها ويقول ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس فلا يدع أحد يمر بين يديه فالسنة أن يضع ستراً أمامه إما جدار وإما عمود وإما كرسي وإما عصاة منصوبة.. ونحو ذلك، فإن لم يتيسر وضع العصا مطروحة أو خطاً بين يديه إذا لم يتيسر شيء قائم، هذا هو السنة، ولا يضره من مر من ورائها، لكنها غير واجبة؛ لأنه ثبت عنه ﷺ أنه في بعض الأحيان صلى إلى غير سترة، فدل على أنها غير واجبة لكنها سنة مؤكدة، وإذا كان في مكان لا يخشى فيه مرور أحد فلا مانع أن يصلي إلى غير سترة، لكن إذا تيسرت السترة فهي أولى وأفضل عملاً بالسنة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/12262/حكم-السترة-وصفتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53806.mp3","categories":["سترة المصلي"]},{"id":14567,"question":"السائل إيهاب من جمهورية مصر العربية، ومقيم بالمملكة العربية السعودية، يقول في سؤاله: روي عن الرسول ﷺ فيما معنى الحديث بأنه لا يجوز لنا المرور من أمام المصلي، ولو نقف أربعين، فما هي المسافة التي من حق المصلي التي يجب أن لا نمر أمامه فيها؟ وينطبق عليه الحديث؟","title":"مقدار المسافة بين السترة والمصلي","answer":"الجواب: يقول النبي ﷺ: لو يعلم المار بين يدي المصلي ماذا عليه يعني: من الإثم لكان أن يقف أربعين خيرًا له من أن يمر بين يدي المصلي وهو حديث صحيح. فالواجب الحذر من المرور بين يدي المصلي، إلا إذا كان أمامه سترة تمر من وراء السترة، والسترة مثل مؤخرة الرحل نحو ذراع أو أقل منه كالذراع، إلا ربع ونحو ذلك، فإذا مررت من ورائها فلا حرج عليك، أو بعيدًا عنه إذا كان ما عنده سترة تمر أمامه بعيدًا بينك وبينه ثلاثة أذرع، أو أكثر بينك وبين محل قدمه ثلاثة أذرع أو أكثر، أما إذا كان له سترة فإنك تمر من وراء السترة، ولا تمر بينه وبين السترة؛ لقوله ﷺ: إذا صلى أحدكم إلى شيء يستر من الناس فأراد أحد أن يجتاز بين يديه فليدفعه، فإن أبى فليقاتله فإنما هو شيطان وقال -عليه الصلاة والسلام-: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة، والحمار، والكلب الأسود وقال ﷺ: إذا صلى أحدكم إلى شيء يستر من الناس فأراد أحد أن يجتاز بين يديه فليدفعه، فإن أبى فليقاتله، فإنما هو شيطان. فالواجب على المؤمن ألا يمر بين يدي أخيه وهو يصلي، وأن يحذر ما نهى الله عنه ورسوله، وعلى المصلي أن يضع سترة أمامه حتى لا يشق على إخوانه، يضع سترة في كرسي مثل يصلي إلى سترة إلى سارية إلى عصا منصوبة، فإن لم يجد وضع العصا قدامه بين يديه مطروحة بين يديه أو خط بين يديه إذا كان في أرض يمكن أن يخط فيها، أو كرسي يضعه أمامه أو ما أشبه ذلك كعباءته يصوبها أمامه حتى يمر المار من ورائها حسب الطاقة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13064/مقدار-المسافة-بين-السترة-والمصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55605.mp3","categories":["سترة المصلي"]},{"id":15140,"question":"سؤاله الآخر يقول: ما حكم المرور أمام المصلي في المساجد؟ وهل هناك مسافة يسمح فيها؟","title":"حكم المرور أمام المصلي ومسافة ذلك","answer":"الجواب: المرور بين يدي المأمومين لا بأس به، ولا حرج فيه.  أما المرور بين يدي الإمام، أو الذي يصلي وحده، هذا لا يجوز، الرسول ﷺ حذر منه، وأخبر أنه أن يقف أربعين خيرًا له من أن يمر بين يدي المصلي، فلا يجوز المرور بين يدي المصلي قريبًا منه في ثلاثة أذرع فأقل، أو بينه وبين السترة.  أما إذا كان بعيد فوق الثلاثة أذرع، فهذا لا حرج فيه؛ لأن رده يشق لبعده، ولأنه لا يعد بين يديه في الحقيقة. والأصل في هذا أنه ﷺ لما صلى في الكعبة جعل بينه وبين الجدار الغربي ثلاثة أذرع، فهذا يدل على أن محل السترة بهذه المثابة فأقل، والأولى أن يبعد أكثر عن المصلي خروجًا من الخلاف، أما إذا كان له سترة فلا يمر بينه وبينها، ولكن يمر من ورائها، نعم.\nالمقدم: هذا ينطبق بالنسبة للمرأة أيضًا؟ الشيخ: والمرأة كذلك. المقدم: لو مرت من...؟\nالشيخ: حتى المرأة، نعم، والحمار والكلب، نعم، بعيدًا منه لا يضره.\nالمقدم: عن ثلاثة أذرع ما...؟\nالشيخ: أو من وراء السترة لا يضره، نعم.","link":"https://binbaz.org.sa/fatwas/13643/حكم-المرور-امام-المصلي-ومسافة-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66504.mp3","categories":["سترة المصلي"]},{"id":15777,"question":"يقول: عندما أقوم إلى الصلاة تأتي بنتي وعمرها ثلاث سنوات، وأخوها وعمره سنة ونصف، ويقومون بحركات الأطفال المعتادة، فكيف أتصرف معهم؟ وهل صلاتي صحيحة عندما يمرون من أمامي ومن حولي؟","title":"حكم مرور الأطفال أمام المصلين","answer":"الجواب: الصلاة صحيحة، وإذا تيسر منعهم -منع الأطفال- فهو المطلوب، وهو المشروع، المشروع أن تمنع أن يمر أحد بين يديك، سواء كان ذلك طفلًا أو بهيمة، أو غير ذلك؛ لقوله ﷺ: إذا صلى أحدكم إلى شيء يستره من الناس فأراد أحد أن يجتاز بين يديه، فليدفعه، فإن أبى فليقاتله، فإنه شيطان. فالمقصود: إذا تيسر منع الطفل أو الدابة فعليك أن تمنع ذلك حسب طاقتك، وإذا غلبك أولئك، فلا حرج عليك، إلا أن يكون المار امرأة أو حمارًا أو كلبًا أسودًا، فإنه يقطع الصلاة، هذه الثلاثة؛ لقوله ﷺ: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة والحمار والكلب الأسود رواه مسلم في الصحيح، أما غير هذه الثلاث فلا يقطع لكن ينقص الأجر، إذا مر رجل ينقص الأجر، أو مر طفل فينقص الأجر إذا لم تمنعه وأنت تستطيع، أو دابة غير الكلب الأسود ينقص الأجر، لكن لا يقطع إلا هذه الثلاث هي التي تبطل الصلاة: المرأة إذا كانت تامة، والحمار، والكلب الأسود، أما الطفلة دون البلوغ فلا تقطع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14365/حكم-مرور-الاطفال-امام-المصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74202.mp3","categories":["سترة المصلي"]},{"id":17018,"question":"يسأل ويقول: من المعلوم أن المرأة البالغة إذا مرت أمام المصلي وهو في صلاته أنها تقطع الصلاة، لكن ما هو الحكم إذا وقع ذلكم الحادث في الحرم، سواء كان في الحرم المكي، أو الحرم المدني؟ جزاكم الله خيرًا.","title":"حكم مرور المرأة أمام المصلي في الحرم","answer":"الجواب: إذا وقع ذلك في الحرم المكي فإنها لا تقطع، وهذه خصوصية للحرم، وقد جاء في الأدلة ما يدل على ذلك، ومن أسباب ذلك أنه في الغالب مظنة الزحام، وعدم القدرة على رد المار، ومن رحمة الله -جل وعلا- أن أسقط هذا الحكم في ذلك، ويلحق بذلك الزحام الشديد في أي مكان في المسجد المدني، أو غيره، إذا كان زحامًا شديدًا، لا يستطيع المصلي أن يمنع المار؛ فإن الحكم واحد في هذا، هذا هو الصواب؛ لأنه عاجز، ولا يستطيع منع المار بين يديه، أما إذا كان هناك قدرة، ولكنه فرط، وتساهل؛ فهذه المرأة البالغة تقطع إذا كانت قريبة منه، والحمار، والكلب الأسود، ثلاثة، هكذا جاء الحديث عن رسول الله ﷺ: يقطع صلاة المرء المسلم إذا لم يكن بين يديه مثل مؤخرة الرحل: المرأة وفي رواية أخرى: الحائض والحمار، والكلب الأسود. أما إذا كان بين يديه مثل مؤخرة الرحل يعني: مثل ذراع، أو حول الذراع منتصب، أو جدار، أو سارية، أو كرسي، أو نحو ذلك، ومرت من ورائه لا تقطع، أو بعيدًا، يعني عن موضع قدميه أكثر من ثلاثة أذرع، هذا بعيد لا يقطع؛ لأن الرسول ﷺ قال: بين يديه والذي قدامه بعيد أكثر من ثلاثة أذرع ليس بين يديه، بل هو بعيد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15805/حكم-مرور-المراة-امام-المصلي-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76707.mp3","categories":["سترة المصلي"]},{"id":17702,"question":"هذا السائل (عبد الله أ. أ) يقول: أصلي النافلة أحيانًا ويحدث أن يسلم الرجل الجالس عن يميني على الرجل الجالس على يساري وأنا في صلاتي، فهل يقطع ذلك الصلاة؟","title":"حكم إمرار اليد أمام المصلي","answer":"الجواب: لا يضر، لا. هذاك المرور أما كونه يمد يده لأخيه والآخر يمد يده لا يضر لا حرج في هذا. نعم.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16655/حكم-امرار-اليد-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77613.mp3","categories":["سترة المصلي"]},{"id":17886,"question":"هل تجب السترة في الصلاة؟ وكم تكون المسافة بينها وبين المصلي؟ وهل يأثم من لا يتخذ السترة أثناء الصلاة؟","title":"هل تجب السترة في الصلاة؟ وكم تكون المسافة بينها وبين المصلي؟","answer":"الجواب: السترة سنة، لقوله ﷺ: إذا صلى أحدكم فليصل إلى سترة وليدنُ منها السنة أن يصلي إليها، وأن يكون بينه وبينها ثلاث أذرع فأقل من قدمه، من قدمه إلى محلها ثلاث أذرع فأقل، ويكون بينه وبينها شيء إذا سجد يكون بينه وبينها شيء يسير؛ حتى لا يصل إليها، هذه السنة وليست واجبة؛ لأنه ثبت عنه ﷺ أنه في بعض الأحيان صلى إلى غير سترة عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/16895/هل-تجب-السترة-في-الصلاة-وكم-تكون-المسافة-بينها-وبين-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59815.mp3","categories":["سترة المصلي"]},{"id":18105,"question":"سمعت حديثًا يحرم المرور بين يدي المصلي، فكم هي المسافة التي يحرم فيها المرور بين يدي المصلي إذا لم يضع أمامه شيئًا؟","title":"المسافة التي يحرم فيها المرور بين يدي المصلي","answer":"الجواب: يقول النبي ﷺ: لو يعلم المار بين يدي المصلي ماذا عليه يعني من الإثم لكان أن يقف أربعين خيرًا له من أن يمر بين يدي المصلي متفق عليه، قال الراوي أبو هريرة : «لا أدري قال أربعين يومًا أو شهرًا أو سنة». والمقصود أن هذا يدل على تحريم ذلك، وأن فيه خطرًا عظيمًا، إذا كان وقوفه أربعين ولو يومًا خيرًا له من أن يمر بين يديه فهذا يدل على أنه أمر خطير لا يجوز. وأرجح ما قيل في ذلك أن الحد ثلاثة أذرع إذا كان ما له سترة، إذا كان وراه ثلاثة أذرع فلا حرج أو كان وراءه سترة فلا حرج، أما إن كان بينه وبين السترة فهذا لا يجوز، أو كان قريبًا منه في أقل من ثلاثة أذرع فهذا لا يجوز. والأصل في هذا أنه ﷺ لما صلى في الكعبة جعل بينه وبين جدار الكعبة الغربي ثلاثة أذرع، قالوا: هذا يدل على أن هذا المقدار هو الذي يعتبر بين يدي المصلي، فإذا كان بعيدًا من هذا المقدار من قدم المصلي فإنه لا يعتبر مارًا بين يديه هذا هو الأرجح. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17140/المسافة-التي-يحرم-فيها-المرور-بين-يدي-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_904/nour_90405.mp3","categories":["سترة المصلي"]},{"id":18263,"question":"يسأل أخونا سؤاله الأخير ويقول: هل للمسجد الحرام، والمسجد النبوي خاصية بمرور الناس أمام المصلي اضطرارًا ودفعًا للحرج؟","title":"حكم السترة للمصلي في المسجد الحرام والمسجد النبوي","answer":"الجواب: هذا للمسجد الحرام، الصواب في المسجد الحرام أنه لا تقطع فيه الصلاة، وأن من مر بين يدي أخيه لا يضره، فلا يمنع المار، ولا يقطع المار الصلاة في المسجد الحرام؛ لأنه مظنة زحمة ومشقة الدفع، والحاجة ماسة إلى المرور بين يدي المصلين في المطاف وغير المطاف. فالصواب في ذلك: أن المصلي في المسجد الحرام لا يمنع ولو مر بين يديه امرأة لم تقطع صلاته؛ لأن الرسول ﷺ لم يحفظ عنه في هذا شيء أنه يمنع المار أو أنها تقطع الصلاة فيه، بل جاء عنه في بعض الأحاديث وإن كان فيها ضعف أنه ما كان يمنع المار في المسجد الحرام، وأنه كان يصلي والناس يمرون بين يديه، لكن فيه ضعف، وثبت عن بعض الصحابة كـابن الزبير أنه كان يصلي والناس يمرون بين يديه؛ ولأن المسجد الحرام مظنة الزحام ولاسيما في أيام الحج، وأيام العمرة في رمضان، قد يصعب رد المار والتحرز من المار، وتلحق بقية أيامه بذلك. أما المسجد النبوي فلم يرد فيه ما ورد في المسجد الحرام، بل ثبت عن أبي سعيد : أنه كان يصلي في المسجد النبوي فأراد أحد أن يمر بين يديه فمنعه، فاشتكاه المار إلى مروان، فدعا أبا سعيد فسأله فأخبره أبو سعيد عن النبي ﷺ أنه قال: إذا صلى أحدكم إلى شيء يستره من الناس فأراد أحد أن يجتاز بين يديه فليدفعه، فإن أبى فليقاتله فإنما هو شيطان. فـأبو سعيد رأى أن مسجد النبي ﷺ مثل غيره يمنع المار فيه، وهذا والله أعلم عند إمكان ذلك، أما إذا كانت الزحمة الشديدة، فإنه في هذه الحالة يلحق بالمسجد الحرام، وهكذا في أي مكان يكون فيه الزحمة الشديدة، لا يمنع المار للضرورة في أي مكان، فإذا ازدحم الناس في أي مكان واحتاج المصلي لأن يصلي فريضته أو الراتبة، فإن المار لا يقطع في هذه الحالة ولا يمنع لعدم إمكان منع المار والتحرز منه، وقد قال الله جل وعلا في كتابه العظيم: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]، فالضرورات لها أحكامها، وهذا منها، والله أعلم. المقدم: جزاكم الله خيرًا يشيع عند عامة الناس سماحة الشيخ أن الذي يمر بين يدي المصلي أن صلاة المصلي تعتبر باطلة والحالة هذه، هل هذا الاعتقاد صحيح؟ الشيخ: هذا فيه تفصيل: إن كان المار امرأة أو حمارًا أو كلبًا أسودًا قطع، كما ثبت في الحديث الصحيح من حديث أبي ذر ، وحديث أبي هريرة وابن عباس، أما إن كان المار غير هذه الثلاث فإنه لا يقطع لكن ينقص، إذا أمكن رده ينقص الصلاة، أما إذا ما أمكن رده بل غلب المصلي فالإثم عليه لا على المصلي، وهذا في غير المسجد الحرام كما تقدم. نعم. وفي غير مواضع الزحمة التي لا حيلة فيها. نعم.","link":"https://binbaz.org.sa/fatwas/17312/حكم-السترة-للمصلي-في-المسجد-الحرام-والمسجد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_909/nour_90904.mp3","categories":["سترة المصلي"]},{"id":18543,"question":"عندما أريد أن أصلي بعض النوافل في البيت، فإنني قد أنسى أن أضع سترة أمامي، ولا أتذكر إلا بعد الشروع في الصلاة، ولكني أنوي أن مكان سجودي بمثابة السترة، فهل عملي هذا له أصل في الشرع؟","title":"حكم الصلاة من غير سترة","answer":"الجواب: السترة سنة كون الناس تصلي إلى سترة سنة، جدار أو سارية أو عمود أو شيء يركز، أو مركى سنة مؤكدة، لكن محل السجود ما هو بسترة، وطرف المصلى ما هو بسترة، السترة شيء ينصب أمامه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17645/حكم-الصلاة-من-غير-سترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73316.mp3","categories":["سترة المصلي"]},{"id":19087,"question":"يقول السائل: ما حكم المرور من أمام المصلي يا فضيلة الشيخ؟","title":"ما حكم المرور من أمام المصلي؟","answer":"الجواب: إذا كان له سترة يكون من وراء السترة تمر من وراء السترة، فأما إن كان ما عنده سترة تبتعد عنه أكثر من ثلاثة أذرع تكون بعيد عن محل قدميه أكثر من ثلاثة أذرع حتى لا تمر بين يديه. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18244/ما-حكم-المرور-من-امام-المصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88320.mp3","categories":["سترة المصلي"]}]
